/* రాయ్ విద్యార్థి యాప్ – 3వ తరగతి పాఠ్యపుస్తకం పాఠాల నోట్స్ + టెస్ట్ ప్రశ్నలు (AP SCERT 2026-27)
   ఈ ఫైల్ మార్చితే index.html మార్చనవసరం లేదు. టీచర్లు యాప్‌లోనే సరిచేయవచ్చు (టీచర్ ప్యానెల్ → 📘 పాఠ్యపుస్తకం నోట్స్). */
(window.RAAY_TB=window.RAAY_TB||{})[3]={"tel": [{"id": "te1","no": 1,"t": "తెలుగు తల్లి","m": [7],"ty": "గేయం","th": "దేశభక్తి","by": "శ్రీశ్రీ (శ్రీరంగం శ్రీనివాసరావు)","sum": "ఈ గేయంలో కవి మన తెలుగు తల్లిని అందాల నిండు చందమామతో, కోరిన కోర్కెలు తీర్చే కల్పవల్లితో పోల్చారు. తెలుగు నేల సంతోషాలు నిండిన చలువరాతి మేడ లాంటిదని, అది మనకు ఎంతో ప్రియమైన నేల అని చెప్పారు. తెలుగు వీరులు భయం లేకుండా, నమ్మకంగా ముందుకు నడిచి కొత్త యుగాన్ని నిర్మించాలని పిలుపునిచ్చారు.","pts": ["గేయం రాసిన కవి: శ్రీశ్రీ – ఆయన ప్రసిద్ధ రచన “మహాప్రస్థానం”, స్వీయ చరిత్ర “అనంతం”.","తెలుగు తల్లి = అందాల నిండు జాబిల్లి, ఆనందాల కల్పవల్లి.","తెలుగు నేల = సంతోషాల చంద్రశాల (చలువరాతి మేడ).","భయం లేకుండా (నిర్భయంగా), నమ్మకంగా (నిశ్చయంగా) ముందుకు నడవాలి.","మన మాతృభాష తెలుగు – దాన్ని ప్రేమించాలి, గౌరవించాలి.","పాడుదాం: “తల్లీ భారతి వందనము” – దాశరథి కృష్ణమాచార్య.","చదువుదాం: “స్వాతంత్ర్య కాంక్ష” – చిన్నప్పుడే భగత్ సింగ్ “దేశభక్తి విత్తనాలు” నాటాలన్నాడు."],"w": [["కల్పవల్లి","కోరిన కోర్కెలు తీర్చేది"],["జాబిల్లి","చందమామ"],["తెనుంగు","తెలుగు"],["చంద్రశాల","చలువరాతి మేడ"],["కనవోయి","చూడవోయి"],["రేడు","రాజు"],["అనుంగు","ప్రియమైన"],["సుదూరం","చాలా దూరం"],["చనవోయి","వెళ్ళవోయి"],["నవ యుగం","కొత్త కాలం"],["నిర్భయంగా","భయం లేకుండా"],["నిశ్చయంగా","నమ్మకంగా, తప్పనిసరిగా"]],"gr": {"t": "విరామ చిహ్నాలు","p": ["వాక్యం చివర ఉండే చుక్క ( . ) – పూర్ణ విరామం (ఫుల్‌స్టాప్). వాక్యం పూర్తయిందని అర్థం.","చదివేటప్పుడు కొద్దిగా ఆగే చోట ( , ) – స్వల్ప విరామం (కామా).","ఉదా: తోటలో జామ, సపోట, మామిడి చెట్లు ఉన్నాయి."]},"qa": [["కవి తెలుగు తల్లిని వేటితో పోల్చారు?","అందాల నిండు జాబిల్లి (చందమామ)తో, కోర్కెలు తీర్చే కల్పవల్లితో పోల్చారు."],["తెలుగు నేల ఎలాంటిదని కవి చెప్పారు?","సంతోషాలు నిండిన చలువరాతి మేడ లాంటిదని, మనకు ప్రియమైన నేల అని చెప్పారు."],["కవి తెలుగు వీరులకు ఇచ్చిన పిలుపు ఏమిటి?","భయం లేకుండా, నమ్మకంగా ముందుకు నడిచి కొత్త యుగాన్ని నిర్మించమన్నారు."],["భగత్ సింగ్ “దేశభక్తి విత్తనాలు” అని ఎందుకు అన్నాడు?","అందరికీ చిన్నప్పటి నుండే దేశం మీద ప్రేమ కలగాలని, స్వాతంత్ర్యం కోసం పోరాడాలని."]],"act": "గేయాన్ని రాగంతో, అభినయంతో పాడండి. మీ అమ్మ గురించి రెండు వాక్యాలు, మాతృభాష తెలుగు గురించి రెండు వాక్యాలు రాయండి. మన జెండా బొమ్మ గీసి రంగులు వేయండి.","kn": "తెలుగు భాష గొప్పతనం: మన తెలుగు పదాలు చాలా వరకు అచ్చుతో ముగుస్తాయి. ఉచ్చారణ మృదువుగా, లయబద్ధంగా ఉంటుంది. అందుకే తెలుగును “ఇటాలియన్ ఆఫ్ ది ఈస్ట్” అంటారు.","qz": [["“తెలుగు తల్లి” గేయం రాసిన కవి ఎవరు?","శ్రీశ్రీ","దాశరథి","చింతా దీక్షితులు","ఆలూరి బైరాగి"],["“జాబిల్లి” అంటే అర్థం ఏమిటి?","చందమామ","సూర్యుడు","నక్షత్రం","మేఘం"],["“కల్పవల్లి” అంటే?","కోరిన కోర్కెలు తీర్చేది","పూల తీగ","పెద్ద చెట్టు","నది"],["“చంద్రశాల” అంటే?","చలువరాతి మేడ","చంద్రుని గుడి","పాఠశాల","పూలతోట"],["“నిర్భయంగా” అంటే?","భయం లేకుండా","భయంతో","నెమ్మదిగా","ఏడుస్తూ"],["“రేడు” అంటే?","రాజు","రెండు","రాత్రి","దారి"],["వాక్యం చివర ఉండే చుక్క ( . )ను ఏమంటారు?","పూర్ణ విరామం","స్వల్ప విరామం","ప్రశ్నార్థకం","ఆశ్చర్యార్థకం"],["స్వల్ప విరామ చిహ్నం (కామా) ఏది?",",",".","?","!"],["కవి “అందాల నిండు జాబిల్లి” అని ఎవరిని అన్నారు?","తెలుగు తల్లి","గోదావరి","సూర్యుడు","భారత మాత"],["చిన్నప్పుడే దేశభక్తి విత్తనాలు నాటాలన్నది ఎవరు?","భగత్ సింగ్","గాంధీజీ","నెహ్రూ","అల్లూరి సీతారామరాజు"],["“తల్లీ భారతి వందనము” గేయం రాసింది?","దాశరథి కృష్ణమాచార్య","శ్రీశ్రీ","నండూరి రామమోహనరావు","ఆలూరి బైరాగి"],["“నవ యుగం” అంటే?","కొత్త కాలం","తొమ్మిది యుగాలు","పాత కాలం","కొత్త ఇల్లు"]]},{"id": "te2","no": 2,"t": "మర్యాద చేద్దాం","m": [7],"ty": "కథ","th": "హాస్యం","by": "పరమానందయ్య గారి శిష్యుల కథ","sum": "కళింగ రాజ్యంలో పరమానందయ్య అనే పండితుడికి పన్నెండు మంది అమాయక శిష్యులు ఉండేవారు. గురువు పొరుగూరు వెళ్ళినప్పుడు ఆయన స్నేహితుడు పేరయ్య వచ్చి “ఓయ్ పరమా!” అని పిలిచాడు. అది అవమానం అనుకుని శిష్యులు ఆయన్ని స్తంభానికి కట్టేశారు. తిరిగి వచ్చిన గురువు “ఇంటికి వచ్చే అతిథులను గౌరవించి మర్యాద చేయాలి” అని చెప్పాడు. ఆ రాత్రి దొంగలు గోడకు కన్నం వేసి లోపలికి వచ్చారు. శిష్యులు వాళ్ళను అతిథులు అనుకుని నీళ్ళు పోసి, పసుపు కుంకుమ పూసి, సాంబ్రాణి పొగ వేశారు. ఆ పొగ చూసి వచ్చిన రాజభటులు దొంగలను పట్టుకున్నారు. దొంగలు దొరికినందుకు రాజుగారు శిష్యులను ఘనంగా సన్మానించారు.","pts": ["ప్రక్రియ: కథ • ఇతివృత్తం: హాస్యం.","పరమానందయ్య – కళింగ రాజ్యంలోని పండితుడు; శిష్యులు 12 మంది, చాలా అమాయకులు.","పేరయ్య “ఒరేయ్ పరమా!” అనడం శిష్యులకు నచ్చలేదు – ఆయన్ని కట్టేశారు.","గురువు మాట: అతిథులను గౌరవించాలి (అతిథి దేవో భవ).","దొంగలకే అతిథి పూజ చేశారు → పొగ చూసి భటులు వచ్చి దొంగలను పట్టుకున్నారు.","పాడుదాం: “రేలా రేలా” – జానపద గేయం.","చదువుదాం: “వికటకవి” – రామకృష్ణుడు కాళికాదేవి ఇచ్చిన పాలు, పెరుగు రెండూ కలిపి తాగాడు. జీవించడానికి తెలివి, ధనం రెండూ కావాలి."],"w": [["పండితుడు","బాగా చదువుకున్నవాడు"],["జనులు","ప్రజలు"],["అమాయకత్వం","తెలియనితనం"],["పొరుగూరు","పక్క ఊరు"],["దంపతులు","భార్యాభర్తలు"],["అఘాయిత్యం","చేయకూడని పని"],["బావురుమను","బోరున ఏడవడం"],["బిక్కమొహం","ఏడుపు మొహం"],["అతిథులు","అనుకోకుండా ఇంటికి వచ్చేవారు"],["మర్యాద","గౌరవం"],["అలికిడి","శబ్దం"],["కుమ్మరించటం","ఒక్కసారిగా పోయడం"],["బంధించి","కట్టివేసి"],["సన్మానించటం","గౌరవించడం"],["ఘనంగా","గొప్పగా"]],"gr": {"t": "ప్రశ్నార్థకం (?), ఆశ్చర్యార్థకం (!), అనుకరణ పదాలు","p": ["ప్రశ్న అడిగే వాక్యం చివర “?” – ప్రశ్నార్థకం. ఉదా: బాబూ! నీ పేరేమిటి?","ఎప్పుడు, ఎక్కడ, ఎందుకు, ఏమిటి, ఎలా, ఎవరు – ప్రశ్నార్థక పదాలు.","ఆశ్చర్యం తెలిపే చోట “!” – ఆశ్చర్యార్థకం. ఉదా: అబ్బో! ఎంత పెద్ద ఏనుగు!","గబగబ, గజగజ, కరకర, గలగల – ఇలాంటివి అనుకరణ పదాలు."]},"qa": [["పరమానందయ్య గారి శిష్యులు ఎలాంటివారు?","చాలా అమాయకులు. వయసు పెరిగినా బుద్ధి పెరగలేదు. వాళ్ళ పనులు నవ్వు తెప్పిస్తాయి."],["శిష్యులకు పేరయ్య మీద ఎందుకు కోపం వచ్చింది?","తమ గురువును “ఓయ్ పరమానందం! ఒరేయ్ పరమా!” అని పిలిచినందుకు."],["శిష్యులు దొంగలకు అతిథి పూజ ఎలా చేశారు?","బిందెలతో నీళ్ళు పోశారు, పసుపు కుంకుమ గంధం పూశారు, సాంబ్రాణి పొగ వేశారు."],["రాజుగారు శిష్యులను ఎందుకు సన్మానించారు?","వారి వల్ల దొంగలు దొరికారు, గురువుగారి ఇల్లు దోచుకోకుండా కాపాడబడింది."]],"act": "మీ ఇంటికి వచ్చిన అతిథులను మీరు ఎలా గౌరవిస్తారో చెప్పండి. “పండు పండు ఏమి పండు? పండు పండు జామ పండు” గేయాన్ని మీకు తెలిసిన పండ్ల పేర్లతో పొడిగించండి. మీకు తెలిసిన హాస్యకథ చెప్పండి.","kn": "గురుకులాలు: పూర్వం విద్యార్థులు గురువు ఇంట్లోనే కొన్ని సంవత్సరాలు ఉంటూ, గురువుకు సేవ చేస్తూ, అన్ని పనులు సొంతంగా చేసుకుంటూ చదువుకునేవారు. ఇప్పుడు అవి గురుకుల పాఠశాలలుగా, సంక్షేమ పాఠశాలలుగా మారాయి.","qz": [["పరమానందయ్య ఏ రాజ్యంలో ఉండేవాడు?","కళింగ","విజయనగరం","కాశీ","మగధ"],["పరమానందయ్య శిష్యులు ఎంత మంది?","12","9","8","10"],["“ఒరేయ్ పరమా!” అని పిలిచింది ఎవరు?","పేరయ్య","రాజుగారు","దొంగ","ఒక శిష్యుడు"],["“అతిథులు” అంటే?","అనుకోకుండా ఇంటికి వచ్చేవారు","దొంగలు","శిష్యులు","రాజభటులు"],["“మర్యాద” అంటే?","గౌరవం","కోపం","భయం","శబ్దం"],["“అలికిడి” అంటే?","శబ్దం","వెలుగు","పొగ","నీరు"],["దొంగలు ఎలా పట్టుబడ్డారు?","ఇంట్లోంచి వచ్చిన పొగ చూసి రాజభటులు వచ్చారు","శిష్యులు కొట్టారు","గురువుగారు పట్టుకున్నారు","పారిపోతూ పడిపోయారు"],["“గజగజ, గలగల” లాంటి పదాలను ఏమంటారు?","అనుకరణ పదాలు","నామవాచకాలు","సర్వనామాలు","ప్రశ్నార్థక పదాలు"],["“బాబూ! నీ పేరేమిటి” – వాక్యం చివర ఏ గుర్తు ఉండాలి?","?",".","!",","],["“!” గుర్తును ఏమంటారు?","ఆశ్చర్యార్థకం","ప్రశ్నార్థకం","పూర్ణ విరామం","స్వల్ప విరామం"],["“వికటకవి” కథలో రామకృష్ణుడు రెండు కుండల్లోవి ఏం చేశాడు?","రెండూ కలిపి తాగేశాడు","పాలు మాత్రమే తాగాడు","పెరుగు మాత్రమే తాగాడు","రెండూ వద్దన్నాడు"],["“పొరుగూరు” అంటే?","పక్క ఊరు","సొంత ఊరు","పట్టణం","అడవి"]]},{"id": "te3","no": 3,"t": "మంచి బాలుడు","m": [8],"ty": "గేయకథ","th": "సహానుభూతి","by": "ఆలూరి బైరాగి","sum": "జోరుగా వాన కురిసి వీధులన్నీ బురదగా మారాయి. ఒక ముసలమ్మ చలికి వణుకుతూ, తడబడే అడుగులతో నడుస్తోంది. ఎవరూ ఆమెకు సాయం చేయలేదు. బడి వదలగానే పిల్లలు సందడి చేస్తూ బయటకు వచ్చారు. వారిలో ఒక బాలుడు జాలితో ముసలమ్మ చేయి పట్టుకుని రోడ్డు దాటించి, ఆమె ఇంటి దగ్గర దిగబెట్టి వచ్చాడు. “ఆ ముసలమ్మ కూడా ఎవరికో అమ్మే కదా! రేపు మన అమ్మకూ ఎవరో ఒకరు సాయం చేయాలి కదా!” అని స్నేహితులతో అన్నాడు. కష్టాల్లో ఉన్నవారికి సాయం చేయని జీవితం వ్యర్థం అని పిల్లలు తెలుసుకున్నారు.","pts": ["ప్రక్రియ: గేయకథ • ఇతివృత్తం: సహానుభూతి • కవి: ఆలూరి బైరాగి.","వాన → బురద → చలికి వణుకుతున్న ముసలమ్మ.","ఒక బాలుడు చేయి పట్టుకుని రోడ్డు దాటించాడు, ఇంటి దగ్గర దిగబెట్టాడు.","నీతి: బలహీనులకు, కష్టాల్లో ఉన్నవారికి సాయం చేయాలి.","పాడుదాం: “కలపండి చేయి చేయి” – దేవులపల్లి కృష్ణశాస్త్రి (కలిసి పని చేస్తే అలసట తెలియదు).","చదువుదాం: “దయ” – దేవదత్తుడు బాణంతో కొట్టిన హంసను గౌతముడు కాపాడాడు. హంస గౌతముని దగ్గరకే వెళ్ళింది."],"w": [["వీధులు","బజారులు"],["జడిసి","భయపడి"],["జనులు","ప్రజలు, జనం"],["త్రోవ","దారి"],["వడి","వేగం"],["సాయం","సహాయం"],["ముదుసలి","ముసలి"],["జాలి","దయ"],["కొనిపోవు","తీసుకుపోవు"],["మనము","మనస్సు"],["దుర్బలులు","బలం లేనివారు"],["మనుజుడు","మనిషి"],["మనుగడ","జీవనం, జీవితం"]],"gr": {"t": "ఏకవచనం – బహువచనం, నామవాచకాలు","p": ["ఒకటి ఉంటే ఏకవచనం, ఒకటి కంటే ఎక్కువ ఉంటే బహువచనం.","కుర్చీ – కుర్చీలు, పలక – పలకలు, కడవ – కడవలు, తలుపు – తలుపులు, చెట్టు – చెట్లు.","మనుషులు, జంతువులు, పక్షులు, ప్రాంతాల పేర్లను తెలిపే పదాలు – నామవాచకాలు.","ఉదా: ఆనంద్, మాధవి (మనుషులు); జింక, కుందేలు (జంతువులు); రామచిలుక, పావురం (పక్షులు)."]},"qa": [["నేలంతా బురదగా ఎందుకు మారింది?","జోరున వాన కురిసినందుకు."],["బాలుడు ముసలమ్మకు ఎలా సహాయం చేశాడు?","ఆమె చేయి పట్టుకుని రోడ్డు దాటించి, ఇంటి దగ్గర దిగబెట్టి వచ్చాడు."],["బాలుడు స్నేహితులకు అమ్మ గురించి ఏమని చెప్పాడు?","ఈ ముసలమ్మ కూడా ఎవరికో అమ్మే; రేపు మన అమ్మకు కూడా ఎవరో సాయం చేయాలి కదా అని."],["ఈ గేయకథలోని నీతి ఏమిటి?","బలహీనులకు, కష్టాల్లో ఉన్నవారికి సాయం చేయాలి. సాయం చేయని జీవితం వ్యర్థం."]],"act": "మీరు ఎవరికైనా చేసిన ఒక మంచి పని గురించి రాయండి. పిల్లవాడికి అవ్వ మూడు బహుమతులు ఇచ్చిందనుకుని కథ పొడిగించండి. మీ ఊరిలోని పెంపుడు జంతువులు, పక్షుల ఆహారపు అలవాట్లు సేకరించండి.","kn": "సహానుభూతి: ఎదుటివారి బాధను, సంతోషాన్ని, దుఃఖాన్ని మనదిగా భావించి స్పందించడమే సహానుభూతి. ఇది ఇతరుల కష్టాలను అర్థం చేసుకుని సాయం చేసే భావనను కలిగిస్తుంది.","qz": [["“మంచి బాలుడు” గేయకథ రాసిన కవి?","ఆలూరి బైరాగి","శ్రీశ్రీ","దాశరథి","దేవులపల్లి కృష్ణశాస్త్రి"],["ముసలమ్మ ఎందుకు వణుకుతోంది?","వానకు, చలికి","ఆకలికి","భయానికి","ఎండకు"],["ముసలమ్మకు సహాయం చేసింది ఎవరు?","ఒక బాలుడు","ఉపాధ్యాయుడు","పోలీసు","ఆమె కొడుకు"],["“త్రోవ” అంటే?","దారి","వేగం","మనిషి","నెమ్మది"],["“దుర్బలులు” అంటే?","బలం లేనివారు","బలవంతులు","ధనవంతులు","పిల్లలు"],["“మనుగడ” అంటే?","జీవనం","మనసు","మనిషి","మాట"],["“నెమ్మదిగా” కు వ్యతిరేక పదం?","వేగంగా","మంచిగా","ఆనందంగా","బలంగా"],["“చెట్టు” బహువచనం?","చెట్లు","చెట్టులు","చెట్టుల్లు","చెట్టా"],["మనుషులు, జంతువులు, ప్రాంతాల పేర్లను ఏమంటారు?","నామవాచకాలు","సర్వనామాలు","అనుకరణ పదాలు","ప్రశ్నార్థకాలు"],["“దయ” కథలో హంసను బాణంతో కొట్టింది ఎవరు?","దేవదత్తుడు","గౌతముడు","శుద్ధోదనుడు","న్యాయాధికారి"],["హంస చివరికి ఎవరి దగ్గరకు వెళ్ళింది?","గౌతముడు","దేవదత్తుడు","రాజు","న్యాయాధికారి"],["“కలపండి చేయి చేయి” గేయం రాసింది?","దేవులపల్లి కృష్ణశాస్త్రి","ఆలూరి బైరాగి","శ్రీశ్రీ","చింతా దీక్షితులు"]]},{"id": "te4","no": 4,"t": "నా బాల్యం","m": [9],"ty": "ఆత్మకథ","th": "కళలు","by": "షేక్ నాజర్ (అక్షరీకరణ: అంగడాల రమణమూర్తి – “పింజారి”)","sum": "బుర్రకథ కళాకారుడు షేక్ నాజర్ తన చిన్ననాటి సంగతులు చెప్పుకున్న పాఠం ఇది. గుంటూరు జిల్లా పొన్నెకల్లులో పుట్టిన ఆయనను తాతయ్య, మామలు “అబ్బుల్ అజీజ్” అని, నాన్న, పెదనాన్నలు “నాజర్” అని పిలిచేవారు. అమ్మానాన్నలు ఏడాదంతా కష్టపడేవారు. చిన్నప్పటి నుండే పాటలు పాడేవాడు. ఒకరోజు హార్మోనిస్టు ఖాదర్ “మీ కుర్రాడికి మంచి తెలివి, కంఠం ఉన్నాయి” అని సంగీతం నేర్పించాడు – శ్రుతి, లయ, గానం, నవ్వడం, ఏడవడం, కోపంగా మాట్లాడడం వంటి నటన నేర్పాడు. పాఠశాల వార్షికోత్సవంలో “ద్రోణ విజయం” నాటికలో ద్రోణాచార్యుడిగా పద్యాలు పాడి బహుమతులు గెలుచుకున్నాడు.","pts": ["ప్రక్రియ: ఆత్మకథ • ఇతివృత్తం: కళలు.","షేక్ నాజర్: 5-2-1920న గుంటూరు జిల్లా పొన్నెకల్లులో జన్మించారు. తల్లిదండ్రులు: షేక్ మస్తాన్, బీనాబీ.","బుర్రకథ కళకు కొత్త మెరుగులు దిద్దారు – పల్నాటి యుద్ధం, వీరాభిమన్యు, బొబ్బిలి యుద్ధం, అల్లూరి సీతారామరాజు కథలు.","1986లో భారత ప్రభుత్వం “పద్మశ్రీ” పురస్కారం ఇచ్చింది. 22-2-1997న మరణించారు.","గురువు: హార్మోనిస్టు ఖాదర్. నాటిక: “ద్రోణ విజయం” (ద్రోణాచార్యుడి పాత్ర).","పాడుదాం: “బంగారు పాపాయి”.","చదువుదాం: “పట్టుదల” – రాహుల్ రోజూ ఒక కథ చదివి పఠన పోటీలో మొదటి బహుమతి గెలిచాడు."],"w": [["ఆశ","కోరిక"],["ఆరుగాలం","ఏడాది అంతా"],["దినచర్య","ప్రతిరోజూ చేసే పనులు"],["గురుదక్షిణ","గురువులకు ఇచ్చే కానుక"],["వార్షికోత్సవం","సంవత్సరం చివర జరుపుకునే వేడుక"],["గుంజ","రాట"],["పామరులు","చదువుకోనివారు"]],"gr": {"t": "నామవాచకాలు, మాండలిక పదాలు","p": ["వస్తువుల పేర్లు (పుస్తకాలు, బూట్లు, బెల్టు), ప్రాంతాల పేర్లు (బాపట్ల, వేమూరు) కూడా నామవాచకాలే.","ఒకే అర్థానికి వేర్వేరు ప్రాంతాల్లో వేర్వేరు పదాలు (మాండలికాలు):","గుంజ = రాట, నిట్టాడు, స్తంభం","చిన్నాన్న = బాబాయి, పినతండ్రి, చిన్నయ్య","బువ్వ = అన్నం, కూడు, మెతుకులు"]},"qa": [["నాజర్ ఏ గ్రామంలో జన్మించాడు?","గుంటూరు జిల్లా పొన్నెకల్లు గ్రామంలో."],["నాజర్ ఏ కళాకారునిగా పేరు పొందాడు?","బుర్రకథ కళాకారునిగా."],["పాఠశాల వార్షికోత్సవంలో నాజర్ వేసిన నాటకం ఏది?","“ద్రోణ విజయం” – అందులో ద్రోణాచార్యుడిగా పద్యాలు, పాటలు పాడాడు."],["ఖాదర్ నాజర్‌కు ఏమి నేర్పించాడు?","శ్రుతి, లయ, గానం, నవ్వడం, ఏడవడం, కోపంగా మాట్లాడడం, ముఖ కవళికలు వంటి నటన."],["ప్రభుత్వం నాజర్‌కు ఏ పురస్కారం ఇచ్చింది?","1986లో పద్మశ్రీ పురస్కారం."]],"act": "మిమ్మల్ని ఇంట్లో ఎవరు ఎలా పిలుస్తారో రాయండి. “నా పేరు కొబ్బరి చెట్టు…” అని ఆత్మకథ పొడిగించండి. ఇవి దేనితో తయారు చేస్తారో రాయండి: కుండ – మట్టి, అద్దం – గాజు, బుట్ట – వెదురు, కొడవలి – ఇనుము.","kn": "లలిత కళలు: మనసుకు హాయిని, ఆనందాన్ని ఇచ్చే కళలు – చిత్రలేఖనం, శిల్పం, సంగీతం, కవిత్వం, నాట్యం మొదలైనవి. మన పెద్దలు 64 కళలు ఉన్నాయని చెప్పారు. చదువుతో పాటు ఒక కళ నేర్చుకోండి.","qz": [["షేక్ నాజర్ ఏ కళలో ప్రసిద్ధుడు?","బుర్రకథ","కూచిపూడి","తోలుబొమ్మలాట","హరికథ"],["నాజర్ జన్మించిన గ్రామం?","పొన్నెకల్లు","గార్లపాడు","కొత్తపల్లి","తెనాలి"],["నాజర్‌కు సంగీతం నేర్పినది ఎవరు?","హార్మోనిస్టు ఖాదర్","షేక్ మస్తాన్","పంతులుగారు","తాతయ్య"],["వార్షికోత్సవంలో నాజర్ వేసిన నాటిక?","ద్రోణ విజయం","సత్య హరిశ్చంద్ర","బొబ్బిలి యుద్ధం","వీరాభిమన్యు"],["నాజర్‌కు 1986లో వచ్చిన పురస్కారం?","పద్మశ్రీ","భారతరత్న","పద్మభూషణ్","జ్ఞానపీఠ్"],["“ఆరుగాలం” అంటే?","ఏడాది అంతా","ఆరు రోజులు","వర్షాకాలం","ఉదయం"],["“పామరులు” అంటే?","చదువుకోనివారు","పండితులు","రైతులు","పిల్లలు"],["“గుంజ”కు మరో పేరు?","రాట","బువ్వ","బాబాయి","కుండ"],["కుండను దేనితో తయారు చేస్తారు?","మట్టి","గాజు","ఇనుము","వెదురు"],["“పట్టుదల” కథలో రాహుల్ ఏ పోటీలో గెలిచాడు?","పఠన పోటీ","పరుగు పందెం","పాటల పోటీ","చిత్రలేఖనం"],["“గురుదక్షిణ” అంటే?","గురువులకు ఇచ్చే కానుక","గురువుల ఇల్లు","దక్షిణ దిక్కు","పాఠశాల ఫీజు"],["“బువ్వ” కు మరో పదం?","అన్నం","నీళ్ళు","పాలు","పండు"]]},{"id": "te5","no": 5,"t": "పొడుపు – విడుపు","m": [10],"ty": "సంభాషణ","th": "భాషాభిరుచి","by": "పాఠం చివర కవి పరిచయం: చింతా దీక్షితులు","sum": "వేసవి సెలవుల్లో గిరి, సూరి మామయ్య ఊరు వెళ్ళారు. రాత్రి సూరి, సీతి, వెంకి మంచం మీద పడుకుని పొడుపు కథలు చెప్పుకున్నారు. “తీసే కొద్దీ పెరిగేదేమిటి?” – నుయ్యి; “వెండి గొలుసు వేయడమే గాని తియ్యలేము” – ముగ్గు; “పచ్చ చొక్కా వాడు చొక్కా విప్పుకొని నూతిలో పడ్డాడు” – అరటిపండు; “ఇంట్లో కలి, ఒంట్లో కలి” – రోకలి, ఆకలి. తర్వాత “ఎక్కడికి? – ఏటికి, ఏ ఏరు? – పాలేరు…” అంటూ గొలుసుకట్టు ఆట ఆడారు. ఇంతలో అమ్మ పడుకోమని పిలిచింది.","pts": ["ప్రక్రియ: సంభాషణ • ఇతివృత్తం: భాషాభిరుచి.","పాత్రలు: సూరి, సీతి, వెంకి (గిరి, సూరి మామయ్య ఊరికి వెళ్ళారు).","పొడుపు కథ = ప్రశ్న (పొడుపు) + జవాబు (విడుపు).","పులి – కుందేలు కథ: పులి అడిగిన పొడుపులకు కుందేలు జవాబులు చెప్పి హాయిగా నీళ్ళు తాగి వెళ్ళింది.","పులి పొడుపులు: పుస్తకం, కొబ్బరికాయ, నాలుక, ఆకాశం – సూర్యచంద్రులు.","పాడుదాం: “చందమామ” – నండూరి రామమోహనరావు.","చదువుదాం: “సమయస్ఫూర్తి” – రజని పొడుపు కథలతో భూతాన్ని ఓడించింది."],"w": [["నుయ్యి","బావి"],["ప్రారంభించు","మొదలుపెట్టు"],["ఏరు","నది"],["పొడుపు","అడిగే కథ (ప్రశ్న)"],["విడుపు","జవాబు"]],"gr": {"t": "సర్వనామాలు","p": ["నామవాచకాలకు బదులుగా వాడే పదాలు – సర్వనామాలు.","ఉదా: విజయ్ తెలివైన బాలుడు. అతను మూడవ తరగతి చదువుతున్నాడు. (విజయ్ → అతను)","అతడు, ఆమె, అది, మేము, నేను, వారు, వీరు, నీవు, మనం – సర్వనామాలు.","నేను – మేము/మనం; నీవు – మీరు; వాడు/ఆమె – వారు/వాళ్ళు; అది – అవి; ఇది – ఇవి."]},"qa": [["వేసవి సెలవుల్లో గిరి, సూరి ఎక్కడికి వెళ్ళారు?","మామయ్య గారి ఊరికి."],["“వెండి గొలుసు వేయడమే గాని తియ్యలేము” – జవాబు ఏమిటి?","ముగ్గు."],["ఈ పాఠంలో సంభాషణలు ఎవరెవరి మధ్య జరిగాయి?","సూరి, సీతి, వెంకి మధ్య."],["పిల్లలు ఏ ఆటలు ఆడారు?","పొడుపు కథలు, గొలుసుకట్టు ఆట."],["కుందేలు వాగు దగ్గరకు ఎందుకు వెళ్ళింది?","దాహం వేసి నీళ్ళు తాగడానికి."]],"act": "మీకు తెలిసిన నాలుగు పొడుపు కథలు రాయండి. ఆవు, మామిడిపండు బొమ్మలు చూసి మీరే కొత్త పొడుపు కథలు తయారు చేయండి. స్నేహితులతో గొలుసుకట్టు ఆట ఆడండి.","kn": "కృత్రిమ మేధస్సు (A.I.): మనిషిలా ఆలోచించే, నేర్చుకునే, నిర్ణయం తీసుకునే టెక్నాలజీ. ఉదా: గూగుల్ అసిస్టెంట్, సిరి, అలెక్సా, రోబోలు. విద్య, వైద్యం, బ్యాంకులు, మొబైల్ ఫోన్లలో వాడుతున్నారు.","qz": [["వేసవి సెలవుల్లో గిరి, సూరి ఎక్కడికి వెళ్ళారు?","మామయ్య ఊరు","అమ్మమ్మ ఊరు","పట్నం","అడవికి"],["“వెండి గొలుసు వేయడమే గాని తియ్యలేము” – జవాబు?","ముగ్గు","గోడ","గొలుసు","నది"],["“పచ్చ చొక్కా వాడు చొక్కా విప్పుకొని నూతిలో పడ్డాడు” – జవాబు?","అరటిపండు","జామపండు","మామిడిపండు","కొబ్బరికాయ"],["“ఇంట్లో కలి, ఒంట్లో కలి” – జవాబులు?","రోకలి, ఆకలి","పులి, పిల్లి","గాలి, ధూళి","చలి, బలి"],["“పైనొక పలక, కిందొక పలక, పలకల నడుమ మెలికల గిలక” – జవాబు?","నాలుక","పుస్తకం","పాము","తలుపు"],["“చెయ్యని కుండ, పొయ్యని నీళ్ళు, వెయ్యని సున్నం” – జవాబు?","కొబ్బరికాయ","కుండ","బావి","మేఘం"],["“తెల్లని పొలంలో నల్లని విత్తనాలు, చేత్తో చల్లుతారు నోటితో ఏరుతారు” – జవాబు?","పుస్తకం","పొలం","ఆకాశం","బొగ్గు"],["“అడవిలో పుట్టింది, మా ఇంటికొచ్చి తైతక్కలాడింది” – జవాబు?","కవ్వం","చీపురు","రోకలి","కట్టెలు"],["“నుయ్యి” అంటే?","బావి","నది","కొండ","ఇల్లు"],["“ఏరు” అంటే?","నది","కొండ","చెట్టు","పొలం"],["నామవాచకాలకు బదులుగా వాడే పదాలు?","సర్వనామాలు","నామవాచకాలు","అనుకరణ పదాలు","ప్రశ్నార్థకాలు"],["“అతడు మూడవ తరగతి చదువుతున్నాడు” – సర్వనామం?","అతడు","మూడవ","తరగతి","చదువుతున్నాడు"],["“చందమామ” గేయం రాసిన కవి?","నండూరి రామమోహనరావు","శ్రీశ్రీ","ఆలూరి బైరాగి","చింతా దీక్షితులు"]]}],"eng": [{"id": "en1","no": 1,"t": "The Recipe Book","m": [7],"ty": "Story","th": "Helping","by": "Poem: The Big Laddoo","sum": "Raju owned a small hotel. Everyone liked his tasty food. One day he got a big order to cook dinner for a party, but he fell ill and fainted. The recipe book saw this and called his friends. The pot cooked rice, the mixer ground the things, the knife sliced and diced the vegetables and the stove helped to cook. When Raju woke up, all the food was ready and delicious. He thanked them all.","te": "రాజుకు ఒక చిన్న హోటల్ ఉంది. ఒక పార్టీకి పెద్ద ఆర్డర్ వచ్చింది కానీ రాజుకు జబ్బు చేసి స్పృహ తప్పాడు. అప్పుడు వంటల పుస్తకం (Recipe Book) తన స్నేహితులు – గిన్నె (pot), మిక్సీ, కత్తి, స్టవ్ – సహాయంతో వంట మొత్తం పూర్తి చేసింది. రాజు లేచి చూసి ఆశ్చర్యపోయి అందరికీ ధన్యవాదాలు చెప్పాడు. నీతి: కష్టంలో ఉన్నవారికి సహాయం చేయాలి.","pts": ["Characters: Raju, the recipe book, the pot, the mixer, the knife, the stove.","Pot → prepares rice • Mixer → grinds • Knife → slices and dices vegetables • Stove → cooks.","Kitchen things: ladle, knife, peeler, pot, funnel, plate, tumbler, bowl.","Poem “The Big Laddoo”: the BIG child threw the BIG laddoo into the BIG sea – BIG SPLISH-SPLASH!","Listening: Omelette steps – crack eggs, add salt & pepper, whisk, heat oil, pour, cook, flip, serve hot."],"w": [["cook","a person who prepares food / to prepare food"],["unfortunately","unluckily (దురదృష్టవశాత్తు)"],["worried","feeling afraid and unhappy (దిగులు)"],["recipe book","a book with cooking methods (వంటల పుస్తకం)"],["slice and dice","to cut and chop into pieces (ముక్కలు చేయు)"],["delicious","tasty (రుచికరమైన)"],["realised","understood (గ్రహించాడు)"]],"gr": {"t": "Singular – Plural • Personal Pronouns • Full stop","p": ["Singular = one: a book, a pen. Plural = more than one: books, pens.","pot – pots, kite – kites, mixer – mixers, bowl – bowls, box – boxes, dish – dishes.","Personal Pronouns: I, He, She, It – used in place of names. e.g. Raju is a cook. He is kind.","Full stop ( . ) comes at the end of a sentence. e.g. He owned a small hotel."]},"qa": [["Who was the owner of the small hotel?","Raju was the owner of the small hotel."],["Why did people like the food in his hotel?","Because the food was very tasty."],["What order did Raju get one day?","A big order to cook dinner for a party."],["Who helped Raju to cook food for the big party?","The recipe book, the pot, the mixer, the knife and the stove."]],"act": "Help your parents in the kitchen and list five things you see there. Match tastes: Laddoo – sweet, Mirchi – spicy, Lemon – sour, Bittergourd – bitter, Salt – salty. Float or sink: put paper, stone, leaf, pencil, eraser, feather, spoon in water and check.","kn": "Round things we can eat: laddoo, orange, grapes. Round things we cannot eat: ball, wheel, coin.","qz": [["Who owned a small hotel?","Raju","Ravi","Sundar","Tenali Rama"],["Who called the friends to help Raju?","The recipe book","The pot","The stove","The knife"],["Which one said “I can slice and dice the vegetables”?","The knife","The mixer","The pot","The stove"],["Which one can grind things in minutes?","The mixer","The knife","The pot","The ladle"],["The plural of “box” is ___.","boxes","boxs","boxies","box"],["The plural of “pot” is ___.","pots","potes","potts","pot"],["“Rani is my sister. ___ likes chess.” Choose the pronoun.","She","He","It","I"],["Which mark comes at the end of “The dog is barking”?",".","?",",","!"],["The meaning of “delicious” is ___.","tasty","bitter","hot","cold"],["Which tool removes the skin of a potato?","Peeler","Knife","Spoon","Rolling pin"],["In the poem, what fell into the BIG sea?","The BIG laddoo","The BIG child","A BIG ball","A BIG boat"],["Lemon tastes ___.","sour","sweet","salty","bitter"]]},{"id": "en2","no": 2,"t": "Tenali Rama And The Thieves","m": [8],"ty": "Story","th": "Wisdom","by": "Poem: Aachoo!","sum": "Tenali Rama was a wise and funny man in the court of King Sri Krishnadevaraya. One evening he saw two thieves hiding near the bushes. He loudly told his wife Sarada that they would put their jewels in a box and drop it into the well. The thieves pulled water from the well all night. At last they got the box – it was full of stones! Tenali Rama thanked them for watering his garden and the thieves ran away.","te": "తెనాలి రామకృష్ణుడు తెలివైనవాడు. పొదల్లో దాక్కున్న దొంగలను చూసి, నగలు పెట్టెలో పెట్టి బావిలో వేస్తామని గట్టిగా భార్యతో చెప్పాడు. నిజానికి పెట్టెలో రాళ్ళు వేశాడు. దొంగలు రాత్రంతా బావిలో నీళ్ళు తోడి, తోటకు నీళ్ళు పెట్టినట్టయింది! పెట్టె తెరిస్తే రాళ్ళు. నీతి: బలం కంటే తెలివి గొప్పది.","pts": ["Tenali Rama – worked in the court of King Sri Krishnadevaraya, Vijayanagaram. Wife: Sarada.","Trick: box full of stones dropped into the well.","Thieves pulled water all night → garden got watered!","Moral: “Being smart is better than being strong.”","Poem “Aachoo!”: the elephant wanted a handkerchief, but asked for a sheet instead.","Fun with words: Chandu Cut Carrots • Anu Ate Apples (same first letter)."],"w": [["wise","clever (తెలివైన)"],["huge","very big"],["thieves","robbers (దొంగలు)"],["hide","keep out of sight (దాక్కోవడం)"],["shocked","surprised and upset"],["reward","prize, gift (బహుమతి)"],["scared","fearful (భయపడిన)"]],"gr": {"t": "Opposites • Nouns • Proper & Common Nouns • Capital letters","p": ["Opposites: tall × short, old × new, empty × full, fast × slow, open × close, happy × sad, big × small, push × pull, up × down.","Nouns = names of persons, places, animals or things (Tenali Rama, garden, box).","Proper Noun = particular name, starts with a capital letter: Sarada, Vijayanagaram, Andhra Pradesh.","Common Noun = general name: thief, well, river, bag, girl.","Capital letters: names, places, days, months, holidays, the word “I”, beginning of a sentence."]},"qa": [["Who was Tenali Rama?","He was a wise and funny man in the court of King Sri Krishnadevaraya."],["Did the couple put all their valuables in the box?","No. They put only stones in the box."],["How did the thieves get the box?","They pulled water out of the well the whole night and got it."],["What did Tenali Rama say to the thieves at last?","Thank you for watering my garden all night! Come to the king’s court for your reward of punishment!"]],"act": "Write your own invitation for a Parents’ Meeting in your school. Draw a rangoli step by step. Make fun sentences with the same first letter: “Sita Sang Songs”.","kn": "Capital letters are used for: Radha, India, I, September, Friday, Deepavali, and the first word of a sentence.","qz": [["Tenali Rama worked in the court of ___.","King Sri Krishnadevaraya","King Akbar","King Sibi","King Ashoka"],["What was in the box dropped into the well?","Stones","Jewels","Money","Clothes"],["What did the thieves do all night?","Pulled water from the well","Slept in the garden","Ran to the king","Cooked food"],["The opposite of “heavy” is ___.","light","big","hard","tight"],["The opposite of “huge” is ___.","tiny","big","tall","old"],["Which of these is a Proper Noun?","Tenali Rama","garden","box","well"],["Which of these is a Common Noun?","school","Raju","Sarada","Andhra Pradesh"],["Which sentence is written correctly?","I live in Andhra Pradesh.","i live in andhra pradesh.","I live in andhra pradesh.","I Live In Andhra pradesh."],["“Being smart is better than being ___.”","strong","rich","tall","fast"],["In the poem, what did the elephant ask for instead of a handkerchief?","a sheet","a shirt","a towel","shoes"],["“reward” means ___.","prize","punishment","robber","garden"],["Tenali Rama’s wife was ___.","Sarada","Sarala","Swathi","Sita"]]},{"id": "en3","no": 3,"t": "The Loyal Mongoose","m": [9],"ty": "Story","th": "Animals & Trust","by": "Conversation: Rabbit’s Payasam","sum": "A farmer and his wife had a new born baby and a pet mongoose. One day the wife went out, leaving the mongoose to take care of the baby. A big snake crawled towards the cradle. The mongoose attacked and killed the snake. When the wife returned, she saw blood on the mongoose’s mouth and thought it had killed her baby. She drove it away with a stick. Inside, she found the baby sleeping safely and the dead snake on the floor. She felt sorry for what she had done.","te": "రైతు భార్య బిడ్డను ముంగిస (mongoose) దగ్గర వదిలి బయటకు వెళ్ళింది. ఒక పాము ఊయల దగ్గరకు వస్తే ముంగిస దాన్ని చంపి బిడ్డను కాపాడింది. తిరిగి వచ్చిన తల్లి ముంగిస నోటికి రక్తం చూసి బిడ్డను చంపిందనుకుని కర్రతో తరిమేసింది. లోపల బిడ్డ క్షేమంగా ఉండటం, చచ్చిన పాము చూసి బాధపడింది. నీతి: ఆలోచించకుండా తొందరపడకూడదు.","pts": ["Characters: farmer, his wife, baby, the loyal mongoose, a snake.","Loyal = faithful (నమ్మకమైన). The mongoose saved the baby.","Lesson: Think before you act – don’t be in a hurry to blame.","Domestic animals: cow, goat, sheep, dog, cat, horse, buffalo, rabbit.","Wild animals: tiger, lion, elephant, fox, wolf, crocodile, deer, giraffe.","Polite requests: “Can you give me some sugar?” • “Thank you.” • “With pleasure.”"],"w": [["trust","belief (నమ్మకం)"],["cradle","a baby bed (ఊయల)"],["return","come back"],["stain","a coloured mark (మరక)"],["temper","heat of mind (కోపం)"],["loyal","faithful (విశ్వాసం గల)"]],"gr": {"t": "Adjectives • Questions ( ? )","p": ["Adjectives (describing words) tell size, shape or colour: a small baby, a round ball, a brown ball.","More adjectives: big, small, long, short, hot, cool, beautiful, flat, round, strong, weak.","Questions end with a question mark ( ? ). Wh-words: who, which, when, what, where, why, how.","Statement → Question: She can play. → Can she play? • You will come. → Will you come? • You like ice cream. → Do you like ice cream?"]},"qa": [["What was the farmer’s pet?","A mongoose."],["Which animal entered the farmer’s house?","A big snake."],["How did the mongoose protect the baby?","It attacked and killed the snake."],["Who sent the mongoose out?","The farmer’s wife."],["How did the wife feel when she saw the baby alive?","She felt sorry for what she had done to the mongoose."]],"act": "Make an animal mask with a paper plate, colours, ears and an ice-cream stick. Write 4 adjectives about your favourite animal. Paste pictures of pet animals.","kn": "A domestic animal lives with us (cow, dog). A wild animal lives in a forest (tiger, lion).","qz": [["What was the farmer’s pet?","A mongoose","A dog","A cat","A parrot"],["Which animal came near the cradle?","A snake","A rat","A fox","A cat"],["Why did the wife get angry?","She saw blood on the mongoose’s mouth","The mongoose ate food","The baby was crying","The snake bit her"],["Which is a wild animal?","Tiger","Cow","Sheep","Dog"],["Which is a domestic animal?","Goat","Wolf","Fox","Crocodile"],["“The ball is red.” – “red” is a/an ___.","Adjective","Noun","Pronoun","Verb"],["Change into a question: “I can eat ice cream.”","Can I eat ice cream?","I can eat ice cream?","Eat I can ice cream?","Ice cream can I eat."],["Which sentence needs a question mark?","Who is your teacher","I am a boy","This is my book","We are playing"],["Which is a polite request?","Can you give me sugar?","Give me sugar.","Sugar give.","Sugar now."],["“cradle” means ___.","a baby bed","a big box","a stick","a cow shed"],["Dog is to home as Lion is to ___.","forest","house","school","river"],["“Loyal” means ___.","faithful","angry","lazy","fast"]]},{"id": "en4","no": 4,"t": "Help Me… Please!","m": [9,10],"ty": "Story","th": "Community Helpers","by": "Poem: The Wheels on the Bus","sum": "A rabbit forgot her name. She asked the farmer, the potter, the barber, the tailor, the cobbler and the fisherman for help. Everyone was busy and sent her to someone else. At last she passed a school where the teacher was teaching the alphabet: “R for Rabbit”. The happy rabbit said, “My name is Rabbit!” and hopped away.","te": "ఒక కుందేలు తన పేరు మర్చిపోయింది. రైతు, కుమ్మరి, మంగలి, దర్జీ, చెప్పులు కుట్టేవాడు, జాలరి – అందరినీ అడిగింది. అందరూ పనిలో బిజీగా ఉన్నారు. చివరికి బడిలో టీచర్ “R for Rabbit” అని చెప్పడం విని తన పేరు “Rabbit” అని తెలుసుకుని సంతోషంగా గెంతుతూ వెళ్ళింది.","pts": ["Order: 1st farmer → 2nd potter → 3rd barber → 4th tailor → 5th cobbler → 6th fisherman → 7th teacher.","Farmer sows seeds • Potter makes pots • Barber trims hair • Tailor stitches clothes • Cobbler mends shoes • Fisherman catches fish • Teacher teaches.","Ordinal numbers: first, second, third, fourth, fifth, sixth, seventh.","Poem: wheels go round and round • train goes chuk chuk • bicycle bell goes tring tring.","Say “Thank you” when someone helps; reply “You’re welcome”."],"w": [["sow","place seeds in the ground (విత్తు)"],["forgot","unable to remember (మర్చిపోయింది)"],["neighbour","a person who lives next to us (పొరుగువారు)"],["quick","skilful, fast"],["trim","cut closely"],["stitch","to sew with a thread (కుట్టు)"],["mend","to repair / fix (బాగు చేయు)"]],"gr": {"t": "Conjunctions: and, or, but • Ordinal numbers","p": ["and – joins two similar ideas: The farmer saw a rabbit and asked its name.","or – shows a choice: Do you want tea or coffee?","but – shows opposite ideas: I like apples but I don’t like bananas.","Ordinal numbers show order: first, second, third, fourth, fifth…"]},"qa": [["Who was sowing seeds?","The farmer."],["What did the rabbit forget?","Her name."],["Where was the cobbler sitting?","Under a tree."],["Who helped the rabbit finally to find her name?","The teacher (R for Rabbit)."]],"act": "Make a colourful kite: frame → paper → decorate → tail → string. Imagine you found a mobile phone – write 4 sentences about it. Match vehicles and sounds: bus – pom pom, train – chuk chuk, bicycle – tring tring.","kn": "Community helpers: farmer, potter, barber, tailor, cobbler, fisherman, teacher, doctor, driver. Everyone’s work is important.","qz": [["What did the rabbit forget?","Her name","Her home","Her food","Her friend"],["A person who mends shoes is a ___.","cobbler","barber","tailor","potter"],["Who makes pots?","Potter","Barber","Farmer","Tailor"],["Who finally helped the rabbit?","The teacher","The farmer","The fisherman","The cobbler"],["The teacher said, “R for ___”.","Rabbit","Rat","Rose","Rain"],["The second person the rabbit met was the ___.","potter","farmer","barber","tailor"],["“I like apples ___ I don’t like bananas.”","but","and","or","so"],["“Do you want tea ___ coffee?”","or","and","but","so"],["If Ravi is first and Sita is second, John is ___.","third","first","fourth","second"],["The bell on the bicycle goes ___.","tring, tring","chuk, chuk","pom, pom","round and round"],["Someone says “Thank you”. You say ___.","You’re welcome","Bye","Go away","Sorry"],["“mend” means ___.","repair","break","sell","sow"]]}],"mat": [{"id": "ma1","no": 1,"t": "Numbers – సంఖ్యలు (4 అంకెలు)","m": [7],"ty": "యూనిట్","th": "9999 వరకు సంఖ్యలు","by": "Maths Magic – 3 (సెమిస్టర్-1)","sum": "999 కి 1 కలిపితే 1000 (వెయ్యి) వస్తుంది. 10 వందలు = 1 వెయ్యి. ఈ యూనిట్‌లో 9999 వరకు నాలుగు అంకెల సంఖ్యలు చదవడం, రాయడం, స్థాన విలువ (Place value), ముఖ విలువ (Face value), విస్తరణ రూపం (Expanded form), సంఖ్యలను పోల్చడం (<, >, =), ఆరోహణ – అవరోహణ క్రమం, దగ్గరి వందకు సవరించడం (Rounding) నేర్చుకుంటాం.","pts": ["నాలుగు స్థానాలు: Thousands (వేలు) | Hundreds (వందలు) | Tens (పదులు) | Ones (ఒకట్లు).","2453 = రెండు వేల నాలుగు వందల యాభై మూడు (Two thousand four hundred and fifty three).","ముఖ విలువ = ఆ అంకె అదే. స్థాన విలువ = అంకె × దాని స్థానం. 2326 లో 3 → స్థాన విలువ 300, ముఖ విలువ 3.","విస్తరణ రూపం: 5243 = 5000 + 200 + 40 + 3. సంక్షిప్త రూపం: 7000 + 100 + 60 + 8 = 7168.","పోల్చడం: ఎక్కువ అంకెలు ఉన్న సంఖ్య పెద్దది. అంకెలు సమానమైతే ఎడమ నుంచి ఒక్కో అంకె పోల్చాలి.","ఆరోహణ క్రమం (Ascending) = చిన్న నుంచి పెద్ద. అవరోహణ క్రమం (Descending) = పెద్ద నుంచి చిన్న.","దగ్గరి వందకు: పదుల అంకె 0–4 అయితే కిందికి, 5–9 అయితే పైకి. 237 → 200, 950 → 1000.","అతిపెద్ద 4 అంకెల సంఖ్య 9999, అతిచిన్నది 1000."],"w": [["Place value","స్థాన విలువ"],["Face value","ముఖ విలువ"],["Expanded form","విస్తరణ రూపం"],["Short form","సంక్షిప్త రూపం"],["Ascending order","ఆరోహణ క్రమం (చిన్న → పెద్ద)"],["Descending order","అవరోహణ క్రమం (పెద్ద → చిన్న)"],["Rounding","దగ్గరి సంఖ్యకు సవరించడం"],["Greater than ( > )","కంటే పెద్దది"],["Less than ( < )","కంటే చిన్నది"],["Abacus","పూసల చట్రం"]],"gr": {"t": "చేసి చూపిన ఉదాహరణలు","p": ["8025: 8 → 8000, 0 → 0, 2 → 20, 5 → 5.","3425, 3421 పోల్చడం: వేలు, వందలు, పదులు సమానం; ఒకట్లు 5 > 1 కాబట్టి 3425 > 3421.","ఆరోహణ క్రమం: 2345, 2354, 2435, 2543.","3, 0, 8, 5 లతో అతిచిన్న 4 అంకెల సంఖ్య 3058 (0358 కాదు – ముందు 0 ఉంటే 4 అంకెల సంఖ్య కాదు). అతిపెద్దది 8530."]},"qa": [["1000 ఎలా వస్తుంది?","999 + 1 = 1000. 10 వందలు = 1 వెయ్యి."],["2326 లో 3 స్థాన విలువ, ముఖ విలువ ఎంత?","స్థాన విలువ 300, ముఖ విలువ 3."],["5243 ను విస్తరణ రూపంలో రాయండి.","5000 + 200 + 40 + 3."],["463 ను దగ్గరి వందకు సవరించండి.","500 – పదుల అంకె 6 (5 లేదా ఎక్కువ) కాబట్టి పైకి."]],"act": "0–9 అంకెల కార్డుల్లో 4 తీసుకుని నాలుగు అంకెల సంఖ్యలు చేసి పదాల్లో రాయండి. మీ చుట్టూ 1000 కంటే ఎక్కువ ఉండే వస్తువులు (బియ్యం గింజలు, ఆకులు…) గుర్తించండి. పూసల చట్రం (spike abacus) పై సంఖ్యలు చూపండి.","kn": "వరంగల్ దగ్గర హన్మకొండలో వెయ్యి స్తంభాల గుడి (శ్రీ రుద్రేశ్వర స్వామి ఆలయం) ఉంది – కాకతీయ రాజు రుద్రదేవుని కాలంలో కట్టారు. మన దేశానికి 7500 కి.మీ. కంటే ఎక్కువ సముద్ర తీరం ఉంది.","qz": [["2453 ను పదాల్లో ఎలా చదువుతారు?","రెండు వేల నాలుగు వందల యాభై మూడు","రెండు వేల నాలుగు వందల ముప్పై ఐదు","నాలుగు వేల రెండు వందల యాభై మూడు","రెండు వందల నలభై ఐదు"],["999 + 1 = ?","1000","9910","1999","100"],["2326 లో 3 స్థాన విలువ?","300","3","30","3000"],["8025 లో 8 స్థాన విలువ?","8000","800","8","80"],["5243 విస్తరణ రూపం?","5000 + 200 + 40 + 3","500 + 200 + 40 + 3","5000 + 2000 + 400 + 3","5 + 2 + 4 + 3"],["7000 + 100 + 60 + 8 = ?","7168","7186","7618","71608"],["ఏది సరైనది?","3425 > 3421","3425 < 3421","3425 = 3421","3421 > 3425"],["అతిపెద్ద 4 అంకెల సంఖ్య?","9999","9000","1000","99999"],["అతిచిన్న 4 అంకెల సంఖ్య?","1000","1111","0000","999"],["3, 0, 8, 5 లతో అతిచిన్న 4 అంకెల సంఖ్య?","3058","0358","3085","8530"],["237 ను దగ్గరి వందకు సవరిస్తే?","200","300","240","250"],["950 ను దగ్గరి వందకు సవరిస్తే?","1000","900","950","990"],["ఆరోహణ క్రమం (చిన్న → పెద్ద) ఏది?","2345, 2354, 2435, 2543","2543, 2435, 2354, 2345","2354, 2345, 2543, 2435","2435, 2345, 2543, 2354"],["250, 275, 300, 325, … తర్వాత సంఖ్య?","350","330","400","326"]]},{"id": "ma2","no": 2,"t": "Addition – కూడిక","m": [8],"ty": "యూనిట్","th": "కూడిక, అంచనా","by": "Maths Magic – 3 (సెమిస్టర్-1)","sum": "సంకరయ్య పండ్ల దుకాణం కథతో కూడిక నేర్చుకుంటాం. ముందు ఒకట్లు, తర్వాత పదులు, తర్వాత వందలు కలపాలి. ఒక స్థానంలో మొత్తం 10 లేదా అంతకంటే ఎక్కువ అయితే, ఒకట్ల అంకె అక్కడ రాసి 1 ని పక్క స్థానానికి తీసుకెళ్లాలి (Carry). సంఖ్యలను దగ్గరి పదికి / వందకు సవరించి సుమారు మొత్తం (Estimation – అంచనా) కూడా చెప్పవచ్చు.","pts": ["కూడిక గుర్తు + ; జవాబును మొత్తం (Sum / Total) అంటారు.","ఎప్పుడూ ఒకట్ల నుంచి మొదలు: ఒకట్లు → పదులు → వందలు.","Carry: 639 + 9 → 9 + 9 = 18; 8 రాసి 1 ని పదులకు → 648.","438 + 476 = 914 (రెండుసార్లు carry).","అంచనా: ₹68 + ₹99 ≈ 70 + 100 = ₹170.","“మొత్తం, కలిపి, అన్నీ కలిపి, ఎక్కువ” అనే మాటలు ఉంటే కూడిక చేయాలి.","ఏ సంఖ్యకు 0 కలిపినా అదే సంఖ్య.","క్రమం మార్చినా మొత్తం మారదు: 45 + 30 = 30 + 45."],"w": [["Addition","కూడిక"],["Sum / Total","మొత్తం"],["Carry over","పక్క స్థానానికి తీసుకెళ్లడం"],["Estimation","అంచనా (సుమారు)"],["Word problem","మాటల లెక్క"],["Altogether","అన్నీ కలిపి"]],"gr": {"t": "చేసి చూపిన ఉదాహరణలు","p": ["126 + 132: ఒకట్లు 6 + 2 = 8, పదులు 2 + 3 = 5, వందలు 1 + 1 = 2 → 258.","మొదటి వారం 345, రెండో వారం 234 గుడ్లు → 579.","రఫీ దగ్గర 783 క్యాండిల్ ప్యాకెట్లు, ఇంకా 237 కొన్నాడు → 1020.","అతిపెద్ద 3 అంకెల సంఖ్య + అతిపెద్ద 2 అంకెల సంఖ్య = 999 + 99 = 1098."]},"qa": [["ఒక బోగీలో 60 మంది, మరో బోగీలో 72 మంది. మొత్తం ఎంతమంది?","60 + 72 = 132 మంది."],["లైబ్రరీలో 468 తెలుగు, 655 ఇంగ్లీష్ పుస్తకాలు. మొత్తం?","468 + 655 = 1123 పుస్తకాలు."],["రాము బొమ్మ ₹120, బంతి ₹45, పుస్తకం ₹85 కొన్నాడు. మొత్తం ఖర్చు?","120 + 45 + 85 = ₹250."],["ప్రియ ₹428 దాచుకుంది, ₹376 బహుమతి వచ్చింది. దగ్గరి వందకు అంచనా?","400 + 400 = సుమారు ₹800."]],"act": "దగ్గరి కిరాణా దుకాణంలో 4 వస్తువుల ధరలు రాసుకుని, రెండేసి వస్తువుల మొత్తం కనుక్కోండి. 1 నుంచి 6 అంకెలను త్రిభుజం ప్రతి వైపు మొత్తం 9 వచ్చేలా అమర్చండి.","kn": "కలిపితే 100 వచ్చే జతలు: 50 + 50, 25 + 75, 40 + 60, 99 + 1. ఇవి గుర్తుంటే లెక్కలు వేగంగా చేయవచ్చు.","qz": [["126 + 132 = ?","258","248","268","358"],["639 + 9 = ?","648","638","658","739"],["438 + 476 = ?","914","904","814","924"],["345 + 234 = ?","579","569","589","679"],["783 + 237 = ?","1020","1010","920","1120"],["60 + 72 = ?","132","122","142","112"],["999 + 99 = ?","1098","1099","1089","1008"],["454 కంటే 8 ఎక్కువ?","462","446","458","472"],["₹68 + ₹99 – దగ్గరి పదికి అంచనా?","₹170","₹160","₹150","₹200"],["మొత్తం 100 వచ్చే జత ఏది?","45 + 55","40 + 50","35 + 75","60 + 50"],["అలీకి 48 పాయింట్లు. బాలకు అలీ కంటే 29 ఎక్కువ. బాల పాయింట్లు?","77","67","87","19"],["₹120 + ₹45 + ₹85 = ?","₹250","₹240","₹205","₹260"],["205 కంటే 5 ఎక్కువ?","210","200","255","215"]]},{"id": "ma3","no": 3,"t": "Subtraction – తీసివేత","m": [9],"ty": "యూనిట్","th": "తీసివేత, అప్పు తీసుకోవడం","by": "Maths Magic – 3 (సెమిస్టర్-1)","sum": "నానమ్మ గోళీల మ్యాజిక్, మరియమ్మ అరటిపండ్లు, దానయ్య తాటాకు విసనకర్రల కథలతో తీసివేత నేర్చుకుంటాం. పెద్ద సంఖ్యను పైన, చిన్న సంఖ్యను కింద రాసి, ఒకట్ల నుంచి మొదలుపెట్టి తీసివేయాలి. పైన ఉన్న అంకె చిన్నదైతే పక్క స్థానం నుంచి 1 అప్పు (Borrow / Regroup) తీసుకోవాలి: 1 పది = 10 ఒకట్లు, 1 వంద = 10 పదులు.","pts": ["తీసివేత గుర్తు − ; జవాబును తేడా (Difference) అంటారు.","156 అరటిపండ్లలో 2 ఇస్తే 156 − 2 = 154.","దానయ్యకు 226 విసనకర్రలు కావాలి, 113 ఉన్నాయి → 226 − 113 = 113 ఇంకా కావాలి.","అప్పు: 337 − 48 → 7 కంటే 8 పెద్దది, 1 పది అప్పు → 17 − 8 = 9; తర్వాత 12 − 4 = 8; 2 → జవాబు 289.","“మిగిలినవి, ఇంకా ఎంత కావాలి, తేడా, తగ్గింది” అనే మాటలు ఉంటే తీసివేత.","సరిచూసుకోవడం: తేడా + చిన్న సంఖ్య = పెద్ద సంఖ్య (289 + 48 = 337).","ఏ సంఖ్య నుంచి 0 తీసినా అదే సంఖ్య; ఒక సంఖ్య నుంచి అదే సంఖ్య తీస్తే 0."],"w": [["Subtraction","తీసివేత"],["Difference","తేడా"],["Borrow / Regroup","అప్పు తీసుకోవడం"],["Left / Remaining","మిగిలినవి"],["How many more","ఇంకా ఎన్ని కావాలి"],["Reduced","తగ్గింది"]],"gr": {"t": "చేసి చూపిన ఉదాహరణలు","p": ["₹885 చొక్కాపై ₹35 తగ్గింపు → 885 − 35 = ₹850.","రమ్యకు ₹750 గౌను కావాలి, ₹550 ఉంది → ఇంకా ₹200 కావాలి.","బడిలో 385 మంది పిల్లలు, 142 గుడ్లు ఉన్నాయి → ఇంకా 243 గుడ్లు కావాలి.","₹425 ని ₹679 చేయాలంటే 679 − 425 = ₹254 కలపాలి."]},"qa": [["300 − 200 = ?","100."],["175 నుంచి 125 తీస్తే?","50."],["సోను దగ్గర ₹50, నోట్‌బుక్ ₹75. ఇంకా ఎంత కావాలి?","75 − 50 = ₹25."],["దానయ్య దగ్గర ₹337, దోసెకు ₹48 ఇచ్చాడు. మిగిలింది?","337 − 48 = ₹289."]],"act": "20 గోళీలు/గింజలతో నానమ్మ మ్యాజిక్ ఆడండి: స్నేహితుడు కొన్ని దాచితే, మిగిలినవి లెక్కించి దాచినవి చెప్పండి (20 − మిగిలినవి).","kn": "తీసివేత కూడికకు వ్యతిరేకం: 8 + 5 = 13 అయితే 13 − 5 = 8, 13 − 8 = 5.","qz": [["156 − 2 = ?","154","158","152","146"],["226 − 113 = ?","113","103","123","339"],["337 − 48 = ?","289","299","389","279"],["885 − 35 = ?","850","820","855","920"],["750 − 550 = ?","200","300","250","100"],["385 − 142 = ?","243","233","253","343"],["679 − 425 = ?","254","264","244","154"],["300 − 200 = ?","100","500","10","200"],["175 − 125 = ?","50","60","40","300"],["సోను దగ్గర ₹50, పుస్తకం ₹75. ఇంకా ఎంత కావాలి?","₹25","₹125","₹35","₹15"],["తీసివేత జవాబును ఏమంటారు?","తేడా (Difference)","మొత్తం (Sum)","లబ్ధం (Product)","భాగఫలం (Quotient)"],["ఒక సంఖ్య నుంచి అదే సంఖ్య తీస్తే?","0","1","అదే సంఖ్య","రెట్టింపు"],["500 − 1 = ?","499","501","490","599"]]},{"id": "ma4","no": 4,"t": "Multiplication – గుణకారం","m": [10],"ty": "యూనిట్","th": "ఎక్కాలు, గుణకారం","by": "Maths Magic – 3 (సెమిస్టర్-1)","sum": "పండ్ల దుకాణంలో వరుసలుగా పేర్చిన పండ్లను లెక్కించడంతో గుణకారం మొదలవుతుంది. గుణకారం అంటే ఒకే సంఖ్యను మళ్ళీ మళ్ళీ కలపడం (repeated addition): 4 × 3 = 4 + 4 + 4 = 12. 6 నుంచి 9 వరకు ఎక్కాలు తయారు చేయడం, 2 అంకెల సంఖ్యను 1 అంకెతో, 2 అంకెల సంఖ్యతో, 3 అంకెల సంఖ్యను 1 అంకెతో గుణించడం నేర్చుకుంటాం. పెద్ద సంఖ్యను విడదీసి (13 = 10 + 3) గుణిస్తే సులభం.","pts": ["గుణ్యం (Multiplicand) × గుణకం (Multiplier) = లబ్ధం (Product). 24 × 4 = 96.","క్రమం మార్చినా లబ్ధం మారదు: 2 × 6 = 6 × 2 = 12.","ఎక్కాలు కలిపి కొత్త ఎక్కం: 5 ఎక్కం + 1 ఎక్కం = 6 ఎక్కం; 6 + 3 = 9 ఎక్కం; 5 + 2 = 7 ఎక్కం.","9 ఎక్కంలో ఒకట్ల అంకె తగ్గుతూ, పదుల అంకె పెరుగుతుంది: 09, 18, 27, 36, 45…","విడదీసి గుణించడం: 6 × 13 = 6 × 10 + 6 × 3 = 60 + 18 = 78.","10 తో గుణిస్తే సంఖ్య చివర 0 వస్తుంది: 26 × 10 = 260.","2 అంకెలు × 2 అంకెలు: 48 × 73 = 3504 (ముందు ఒకట్లతో, తర్వాత పదులతో గుణించి కలపాలి)."],"w": [["Multiplication","గుణకారం"],["Multiplicand","గుణ్యం"],["Multiplier","గుణకం"],["Product","లబ్ధం"],["Table","ఎక్కం"],["Repeated addition","మళ్ళీ మళ్ళీ కూడిక"],["Dozen","డజను (12)"],["Row","వరుస"]],"gr": {"t": "చేసి చూపిన ఉదాహరణలు","p": ["4 పొట్లాలు, ఒక్కోదానిలో 24 టపాసులు → 24 × 4 = 96.","12 అరటిపండ్లు చొప్పున 5 సంచులు → 12 × 5 = 60.","47 వేప చెట్లు చొప్పున 3 వరుసలు → 47 × 3 = 141.","72 మంది చొప్పున 23 బోగీలు → 72 × 23 = 1656."]},"qa": [["పెన్ను ₹4. 32 పెన్నుల ధర?","32 × 4 = ₹128."],["ఒక పెట్టెలో 50 పుస్తకాలు. 4 పెట్టెల్లో?","50 × 4 = 200 పుస్తకాలు."],["10 వరుసలు, ఒక్కో వరుసలో 25 మామిడి చెట్లు. మొత్తం?","25 × 10 = 250 చెట్లు."],["ఒక బస్సులో 48 మంది. 26 బస్సుల్లో?","48 × 26 = 1248 మంది."]],"act": "అగ్గిపుల్లలతో 5 ఎక్కం తయారు చేయండి. 1–10 అంకెల కార్డులతో “లబ్ధం సరిపోయే కార్డులు” ఆట ఆడండి. 5, 2 ఎక్కాలు కలిపి 7 ఎక్కం రాయండి.","kn": "10 పెన్సిళ్ల ప్యాకెట్లు: 2 → 20, 8 → 80, 14 → 140, 57 → 570. 10 తో గుణించాలంటే సంఖ్య చివర 0 చేరిస్తే చాలు!","qz": [["24 × 4 = ?","96","86","28","106"],["12 × 5 = ?","60","17","50","65"],["47 × 3 = ?","141","121","151","131"],["6 × 13 = ?","78","68","19","83"],["72 × 23 = ?","1656","1556","1646","166"],["48 × 73 = ?","3504","3404","3514","121"],["32 × 4 = ?","128","124","36","138"],["26 × 10 = ?","260","36","206","2610"],["9 × 7 = ?","63","56","72","16"],["8 × 6 = ?","48","42","54","14"],["గుణకారం జవాబును ఏమంటారు?","లబ్ధం (Product)","మొత్తం (Sum)","తేడా (Difference)","గుణకం (Multiplier)"],["6 ఎక్కం ఏ రెండు ఎక్కాలు కలిపితే వస్తుంది?","5 ఎక్కం + 1 ఎక్కం","4 ఎక్కం + 3 ఎక్కం","5 ఎక్కం + 2 ఎక్కం","3 ఎక్కం + 2 ఎక్కం"],["ఒక సంచిలో 9 నారింజలు. 5 సంచుల్లో?","45","14","54","40"],["48 × 26 = ?","1248","1148","1258","74"]]}],"evs": [{"id": "ev1","no": 1,"t": "My Family – నా కుటుంబం","m": [7],"ty": "పాఠం","th": "కుటుంబం, వృత్తులు","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "ఆదివారం పవన్ ఆడుకోవడానికి అను ఇంటికి వచ్చాడు. అను తన కుటుంబ ఫోటో ఆల్బమ్ చూపించి తాతయ్య, నానమ్మ, అమ్మ, నాన్న, తమ్ముళ్లు రిషి, రోహన్, పెంపుడు కుక్క షీరోను పరిచయం చేసింది. పవన్ కుటుంబంలో ముగ్గురే – నాన్న వెంకట్, అమ్మ మణి, పవన్. కుటుంబంలో ప్రతి ఒక్కరికీ ఒక పాత్ర ఉంటుంది; అందరూ పనులు పంచుకుని ప్రేమగా ఒకరినొకరు చూసుకుంటారు. పండుగలు కుటుంబాన్ని ఒక్క చోటికి చేరుస్తాయి. మన చుట్టూ రకరకాల వృత్తుల వారు మనకు సహాయం చేస్తారు. గృహోపకరణాలు పనులను త్వరగా పూర్తి చేస్తాయి. మనం కుటుంబంలో ఎవరో ఒకరిని పోలి ఉంటాం.","pts": ["కుటుంబం: తాతయ్య, నానమ్మ/అమ్మమ్మ, అమ్మ, నాన్న, అన్నదమ్ములు, అక్కచెల్లెళ్లు (Siblings), పెంపుడు జంతువులు.","Family flow chart – కుటుంబ సభ్యుల సంబంధాలను గీతలతో చూపే చిత్రం.","పెద్దలు మంచి నడవడిక నేర్పుతారు; పిల్లలు ఇంటి పనుల్లో సాయం చేసి పెద్దలను గౌరవించాలి.","పండుగలు (సంక్రాంతి, దీపావళి, రంజాన్, క్రిస్మస్) కుటుంబ సంతోషాన్ని పెంచుతాయి.","వృత్తులు: దర్జీ, క్షురకుడు, చెప్పులు బాగుచేసేవారు, బుట్టలు అల్లేవారు, పారిశుధ్య కార్మికులు – అన్ని వృత్తులనూ గౌరవించాలి.","Home appliances: ఫ్రిజ్, మిక్సీ, వాషింగ్ మెషిన్, ఫ్యాన్ – సమయం ఆదా. పాలు, పెరుగు ఫ్రిజ్‌లో దాస్తాం.","మంచి అలవాట్లు: చెప్పులు బయట వరుసగా పెట్టడం, పెద్దలకు నమస్కరించడం, పుట్టినరోజున మొక్క నాటడం, అందరూ కలిసి భోజనం చేయడం.","రంగు, ఎత్తు చూసి ఎవరినీ ఎగతాళి చేయకూడదు – ప్రతి ఒక్కరూ ప్రత్యేకం."],"w": [["Family","కుటుంబం"],["Grandparents","తాతయ్య, నానమ్మ/అమ్మమ్మ"],["Siblings","తోబుట్టువులు"],["Pet","పెంపుడు జంతువు"],["Resemble","పోలి ఉండటం"],["Profession / Occupation","వృత్తి"],["Home appliances","గృహోపకరణాలు"],["Festival","పండుగ"],["Sanitation worker","పారిశుధ్య కార్మికుడు"]],"gr": {"t": "ఆలోచించండి – చర్చించండి","p": ["రవి, అతని చెల్లెలు ఇంటి పనులు పంచుకుంటారు – మంచిదే; పని త్వరగా, సంతోషంగా అవుతుంది.","మీనా అన్ని పనులు ఒక్కతే చేసి అలసిపోతుంది – కుటుంబ సభ్యులు సాయం చేయాలి.","హేమ స్వీపర్ పనిని గౌరవిస్తుంది – సరైనదే; వారి వల్లే మన పరిసరాలు శుభ్రంగా ఉంటాయి."]},"qa": [["కుటుంబం అంటే ఏమిటి?","కలిసి జీవించే తాతయ్య, నానమ్మ, అమ్మ, నాన్న, అన్నదమ్ములు, అక్కచెల్లెళ్లు – వీరంతా కుటుంబం."],["Family flow chart అంటే ఏమిటి?","కుటుంబ సభ్యుల మధ్య సంబంధాలను గీతలతో చూపే చిత్రం."],["గృహోపకరణాలు ఎందుకు వాడతాం?","పనులు త్వరగా పూర్తి చేసి సమయం ఆదా చేయడానికి."],["చెల్లికి జ్వరం వస్తే ఎలా చూసుకోవాలి?","దగ్గర ఉండి, నీళ్లు, మందులు సమయానికి ఇవ్వడంలో పెద్దలకు సాయం చేసి, ప్రేమగా మాట్లాడాలి."]],"act": "బటన్లు, అగ్గిపుల్లలతో మీ కుటుంబం బొమ్మ చేయండి. మీ కుటుంబ flow chart గీయండి. ఇంట్లో ఎవరు ఎవరిని పోలి ఉంటారో అడిగి పట్టిక నింపండి.","kn": "డాక్టర్, లాయర్, పోలీస్, ఇంజినీర్ – ఇవి professions (వృత్తులు). మన ఊరిలో రకరకాల పనులు చేసేవారు ఉంటారు – అందరి పనీ ముఖ్యమే.","qz": [["అన్నదమ్ములు, అక్కచెల్లెళ్లను ఇంగ్లీష్‌లో ఏమంటారు?","Siblings","Parents","Grandparents","Neighbours"],["పాలు, పెరుగు దాచే గృహోపకరణం?","Refrigerator (ఫ్రిజ్)","Fan (ఫ్యాన్)","Cooler (కూలర్)","Mixer (మిక్సీ)"],["కుటుంబ సభ్యులను గీతలతో చూపే చిత్రం?","Family flow chart","Map (పటం)","Calendar","Clock"],["అను పెంపుడు కుక్క పేరు?","షీరో","టామీ","రాజు","మోతీ"],["పవన్ కుటుంబంలో ఎంత మంది?","3","5","2","6"],["రోడ్లు ఊడ్చి కాలువలు శుభ్రం చేసేవారు?","పారిశుధ్య కార్మికులు","రైతులు","దర్జీలు","డ్రైవర్లు"],["గృహోపకరణాలు ఎందుకు?","పని త్వరగా చేసి సమయం ఆదా","ఆడుకోవడానికి","అలంకరణకు","నిద్రపోవడానికి"],["ఇతరుల రంగు, ఎత్తు చూసి ఏం చేయాలి?","గౌరవంగా, ప్రేమగా ఉండాలి","ఎగతాళి చేయాలి","దూరం పెట్టాలి","పేర్లు పెట్టాలి"],["“Resemble” అంటే?","పోలి ఉండటం","పరుగెత్తడం","పాడటం","మర్చిపోవడం"],["కుటుంబ సభ్యులందరినీ ఒక్క చోటికి చేర్చేవి?","పండుగలు","పరీక్షలు","టీవీ","ఫోన్లు"],["డాక్టర్, లాయర్, పోలీస్ – ఇవి ఏవి?","వృత్తులు (Professions)","పండుగలు","గృహోపకరణాలు","జంతువులు"],["నాజీరా బట్టలు కుడుతుంది. ఆమె వృత్తి?","దర్జీ (Tailor)","క్షురకుడు","రైతు","డాక్టర్"]]},{"id": "ev2","no": 2,"t": "Plants Around Us – మన చుట్టూ మొక్కలు","m": [7],"ty": "పాఠం","th": "మొక్కలు","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "గీత పుట్టినరోజున గీత, తమ్ముడు వేణు తోటలో మొక్కలు నాటారు. “మొక్క నేల నుంచి నీళ్లు ఎలా తీసుకుంటుంది?” అని గీత అడిగితే నాన్న టమాటా మొక్క చూపించి భాగాలు వివరించారు – వేరు, కాండం, ఆకులు, పువ్వులు, పండ్లు. మొక్కల్లో చిన్న మొక్కలు (Herbs), పొదలు (Shrubs), చెట్లు (Trees), ఎగబాకే తీగలు (Climbers), పాకే తీగలు (Creepers) అనే రకాలు ఉన్నాయి. ఆకులు మొక్కకు ఆహారం తయారు చేస్తాయి. మొక్కలు మనకు ఆహారం, గాలి, నీడ, కలప, మందులు, పత్తి, నూనె, కాగితం ఇస్తాయి. “ఏక్ పేడ్ మా కే నామ్” – అమ్మ పేరు మీద ఒక మొక్క నాటి, గ్రీన్ పాస్‌పోర్ట్‌లో దాని పెరుగుదల రాస్తాం.","pts": ["Root (వేరు): మొక్కను నేలలో పట్టి ఉంచుతుంది; నీరు, పోషకాలు పీలుస్తుంది. క్యారెట్, బీట్‌రూట్, ముల్లంగి వేర్లలో ఆహారం నిల్వ.","Stem (కాండం): మొక్కను నిటారుగా నిలుపుతుంది; నీటిని అన్ని భాగాలకు తీసుకెళ్తుంది. చెట్ల లావు కాండం = Trunk (మాను), దానిపై Bark (బెరడు).","Leaf (ఆకు): మొక్కకు ఆహారం తయారు చేస్తుంది. ఆకులకు ఈనెలు (veins) ఉంటాయి.","Flower (పువ్వు) పండుగా మారుతుంది; Fruit (పండు) లో విత్తనాలు ఉంటాయి.","మొక్క పెరగడానికి గాలి, నీరు, సూర్యరశ్మి, నేల కావాలి.","Herbs: కొత్తిమీర, పాలకూర, మెంతి • Shrubs: గులాబీ, మందార • Trees: మర్రి, చింత, మామిడి, కొబ్బరి • Climbers: ద్రాక్ష, కాకర • Creepers: పుచ్చ, గుమ్మడి.","ఆకుల ఉపయోగాలు: టీ; వేప, తులసి – మందులు; కొత్తిమీర, కరివేపాకు, మునగాకు – ఆహారం; అరిటాకు, మోదుగాకు – విస్తరాకులు.","అద్భుతాలు: ప్రపంచంలో అతి చిన్న మొక్క వుల్ఫియా; భారతదేశంలో పెద్ద చెట్టు మర్రి, పెద్ద పండు పనస; పొడవైన గడ్డి వెదురు; ప్రపంచంలో పెద్ద పువ్వు రఫ్లీషియా."],"w": [["Root","వేరు"],["Stem","కాండం"],["Leaf","ఆకు"],["Trunk","మాను"],["Bark","బెరడు"],["Herbs","చిన్న మొక్కలు"],["Shrubs","పొదలు"],["Climbers","ఎగబాకే తీగలు"],["Creepers","నేలపై పాకే తీగలు"],["Veins","ఈనెలు"],["Nutrients","పోషకాలు"],["Aroma","సువాసన"]],"gr": {"t": "భాగం – దాని పని","p": ["విత్తనాలు ఉండేది → పండు (Fruit)","మొక్కను నేలలో పట్టి ఉంచేది → వేరు (Root)","నీటిని తీసుకెళ్లేది → కాండం (Stem)","ఆహారం తయారు చేసేది → ఆకు (Leaf)"]},"qa": [["మొక్క భాగాలు ఏవి?","వేరు, కాండం, ఆకులు, పువ్వులు, పండ్లు."],["ఆహారం తయారు చేసే భాగం ఏది?","ఆకు."],["వేర్లు మొక్కకు ఎలా సహాయపడతాయి?","మొక్కను నేలలో గట్టిగా పట్టి ఉంచుతాయి; నీరు, పోషకాలు పీలుస్తాయి."],["చిన్న కుండీలో మొక్క తేలికగా పడిపోతోంది. ఎందుకు?","వేర్లు బలహీనంగా ఉండటం వల్ల."],["గ్రీన్ పాస్‌పోర్ట్ అంటే?","మనం నాటిన మొక్క పేరు, శాస్త్రీయ నామం, నాటిన తేదీ, స్థలం, దాని పెరుగుదల రాసే కార్డు."]],"act": "మొక్క బొమ్మ గీసి భాగాల పేర్లు రాయండి. రకరకాల ఆకులు సేకరించి వాటి ఆకారం గీయండి. కళ్లకు గంతలు కట్టి నిమ్మ, వేప, తులసి, పుదీనా ఆకులను వాసనతో గుర్తించండి. టీచర్ సహాయంతో కిచెన్ గార్డెన్ పెంచండి.","kn": "మొక్కలు కార్బన్ డై ఆక్సైడ్ తీసుకుని మనం పీల్చే ఆక్సిజన్ ఇస్తాయి. వుల్ఫియా అనే చిన్న మొక్క కలుషిత నీటిని స్పాంజ్‌లా శుభ్రం చేస్తుంది.","qz": [["ఆహారం తయారు చేసే మొక్క భాగం?","ఆకు (Leaf)","వేరు (Root)","పువ్వు (Flower)","కాండం (Stem)"],["మొక్కను నేలలో పట్టి ఉంచేది?","వేరు (Root)","ఆకు (Leaf)","పండు (Fruit)","పువ్వు (Flower)"],["నీటిని అన్ని భాగాలకు తీసుకెళ్లేది?","కాండం (Stem)","పువ్వు","పండు","విత్తనం"],["విత్తనాలు ఉండే భాగం?","పండు (Fruit)","ఆకు","వేరు","కాండం"],["వేరులో ఆహారం నిల్వ చేసేది?","క్యారెట్","టమాటా","మామిడి","గులాబీ"],["గులాబీ, మందార ఏ రకం?","Shrubs (పొదలు)","Herbs","Trees","Creepers"],["పుచ్చ, గుమ్మడి ఏ రకం?","Creepers (పాకే తీగలు)","Climbers","Shrubs","Trees"],["కొత్తిమీర, పాలకూర ఏ రకం?","Herbs (చిన్న మొక్కలు)","Trees","Shrubs","Climbers"],["చెట్టు లావు కాండాన్ని ఏమంటారు?","Trunk (మాను)","Bark","Root","Vein"],["భారతదేశంలో అతి పెద్ద చెట్టు?","మర్రి","కొబ్బరి","వేప","మామిడి"],["ప్రపంచంలో అతి చిన్న మొక్క?","వుల్ఫియా","వెదురు","తులసి","గడ్డి"],["“ఏక్ పేడ్ మా కే నామ్” అంటే?","అమ్మ పేరు మీద ఒక మొక్క","ఒక చెట్టు నరకడం","పండ్ల తోట","అడవి యాత్ర"],["మొక్క పెరగడానికి కావలసినవి?","గాలి, నీరు, సూర్యరశ్మి, నేల","చీకటి మాత్రమే","ప్లాస్టిక్","ఉప్పు నీరు"]]},{"id": "ev3","no": 3,"t": "Animals Around Us – మన చుట్టూ జంతువులు","m": [8],"ty": "పాఠం","th": "జంతువులు, పక్షులు","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "సెలవుల్లో సూర్య, తన కజిన్స్‌తో జూకి వెళ్లి ఏనుగు, పులి, సింహం, చీతా చూశాడు. కొన్ని జంతువులు మనతో ఉంటాయి – సాధు/పెంపుడు జంతువులు (Domestic). అడవిలో ఉండేవి అడవి జంతువులు (Wild). జంతువులు నడుస్తాయి, పాకుతాయి, దూకుతాయి, ఈదుతాయి, ఎగురుతాయి. నేలపై ఉండేవి (Terrestrial), నీటిలో ఉండేవి (Aquatic), రెండింటిలో ఉండేవి (Amphibians). మొక్కలు మాత్రమే తినేవి శాకాహారులు, మాంసం తినేవి మాంసాహారులు, రెండూ తినేవి సర్వాహారులు. జంతువులు శబ్దాలు, వాసన, కదలికలతో సమాచారం పంచుకుంటాయి. మొక్కలు, జంతువులు, పక్షులు కలిసి జీవిస్తాయి – వాటిని కాపాడాలి.","pts": ["Domestic: పిల్లి, కుక్క, మేక, గేదె, ఎద్దు, ఆవు • Wild: సింహం, పులి, జిరాఫీ, ఏనుగు, నక్క.","కదలిక: పాము పాకుతుంది; కంగారూ, కప్ప దూకుతాయి; చేప మొప్పలు, తోకతో ఈదుతుంది; పక్షులు ఎగురుతాయి.","Terrestrial: ఆవు, కుక్క, పిల్లి, కోడి • Aquatic: చేప, రొయ్య • Amphibians: కప్ప, మొసలి, తాబేలు.","నివాసాలు: సింహం – గుహ (Den), పక్షి – గూడు (Nest), పాము/ఎలుక – బొరియ (Burrow), పశువులు – పాక (Shed).","Herbivores: ఆవు, గేదె, గుర్రం, ఏనుగు, జింక • Carnivores: పులి, సింహం, నక్క, మొసలి • Omnivores: ఎలుగుబంటి, కాకి, కుక్క.","రాబందు, కాకి, నక్క చనిపోయిన జంతువులను తింటాయి – ప్రకృతి పారిశుధ్య కార్మికులు (Scavengers).","తేనెటీగలు డాన్స్‌తో పువ్వుల జాడ చెబుతాయి; కుక్క తోక ఊపి సంతోషం చెబుతుంది.","జాతీయ పక్షి – నెమలి; జాతీయ జంతువు – రాయల్ బెంగాల్ టైగర్. అతి పెద్ద పక్షి ఉష్ట్రపక్షి, అతి చిన్నది హమ్మింగ్‌బర్డ్."],"w": [["Domestic animals","సాధు/పెంపుడు జంతువులు"],["Wild animals","అడవి జంతువులు"],["Terrestrial","నేలపై నివసించేవి"],["Aquatic","నీటిలో నివసించేవి"],["Amphibians","ఉభయచరాలు"],["Herbivores","శాకాహారులు"],["Carnivores","మాంసాహారులు"],["Omnivores","సర్వాహారులు"],["Den","గుహ"],["Nest","గూడు"],["Burrow","బొరియ"],["Communicate","సమాచారం పంచుకోవడం"]],"gr": {"t": "ఆలోచించండి","p": ["పక్షుల మీద రాళ్లు విసరడం తప్పు – వాటికి బాధ కలుగుతుంది.","చెట్లు, అడవులు నరకడం కంటే మొక్కలు, జంతువులను కాపాడటం ప్రకృతికి మంచిది.","వేసవిలో ఇంటి బయట చిన్న గిన్నెలో నీళ్లు, గింజలు పెడితే పక్షులకు, చిన్న జంతువులకు సహాయం."]},"qa": [["Domestic, Wild జంతువుల తేడా?","మనతో ఉంటూ మచ్చిక చేసుకోగలిగేవి Domestic; అడవిలో ఉండేవి Wild."],["శాకాహారులు ఏమి తింటాయి?","మొక్కలు మాత్రమే – గడ్డి, ఆకులు."],["జంతువులు ఎలా సమాచారం పంచుకుంటాయి?","శబ్దాలు, వాసన, శరీర కదలికలతో."],["ఉభయచరాలు అంటే?","నేలపై, నీటిలో రెండు చోట్లా జీవించేవి – కప్ప, మొసలి, తాబేలు."]],"act": "“Run like a lion, Swing like a monkey…” రైమ్‌ని అభినయంతో పాడండి. ఉదయం కళ్లు మూసుకుని పక్షుల శబ్దాలు వినండి. “జంతువులను కాపాడండి” అనే నినాదం రాయండి.","kn": "పక్షులు ఉదయం గుంపులుగా ఆహారం కోసం వెళ్లి సాయంత్రం తిరిగి వస్తాయి – అప్పుడే ఎక్కువ శబ్దాలు చేస్తాయి. వానపాము నేలను మెత్తగా చేస్తుంది.","qz": [["ఆవు, మేక, కుక్క ఏ రకం జంతువులు?","Domestic (సాధు)","Wild (అడవి)","Aquatic (నీటి)","Amphibians"],["అడవి జంతువు ఏది?","పులి","ఆవు","గేదె","మేక"],["నేలపై, నీటిలో రెండింటిలో జీవించేది?","కప్ప","చేప","ఆవు","కాకి"],["మొక్కలు మాత్రమే తినే జంతువులు?","Herbivores (శాకాహారులు)","Carnivores","Omnivores","Scavengers"],["పులి, సింహం ఏ రకం?","Carnivores (మాంసాహారులు)","Herbivores","Omnivores","Amphibians"],["ఎలుగుబంటి, కాకి ఏ రకం?","Omnivores (సర్వాహారులు)","Herbivores","Carnivores","Aquatic"],["సింహం నివాసం?","Den (గుహ)","Nest (గూడు)","Burrow (బొరియ)","Shed (పాక)"],["పాము, ఎలుక నివాసం?","Burrow (బొరియ)","Nest","Den","Shed"],["మన జాతీయ పక్షి?","నెమలి","చిలుక","కాకి","పావురం"],["మన జాతీయ జంతువు?","రాయల్ బెంగాల్ టైగర్","సింహం","ఏనుగు","ఆవు"],["తేనెటీగలు పువ్వుల జాడ ఎలా చెబుతాయి?","ప్రత్యేక డాన్స్‌తో","పాటతో","రంగు మార్చి","నిద్రపోయి"],["అతి పెద్ద పక్షి?","ఉష్ట్రపక్షి","హమ్మింగ్‌బర్డ్","కాకి","నెమలి"],["పక్షుల మీద రాళ్లు విసరడం?","తప్పు – వాటికి బాధ","సరైనది","మంచి ఆట","అవసరం"]]},{"id": "ev4","no": 4,"t": "Our Body – మన శరీరం","m": [8,9],"ty": "పాఠం","th": "శరీరం, ఆరోగ్యం, భద్రత","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "టీచర్ “Two little eyes to see…” రైమ్‌తో శరీర భాగాలు నేర్పించారు. మన శరీరం తల, మొండెం (Trunk), కాళ్లు-చేతులు (Limbs) అనే మూడు భాగాలు. కళ్లు చూడటానికి, చెవులు వినడానికి, ముక్కు వాసనకు, శ్వాసకు, నాలుక రుచికి, చర్మం స్పర్శకు – ఇవి ఐదు జ్ఞానేంద్రియాలు. కొందరు చూడలేరు, వినలేరు, నడవలేరు – వారిని దివ్యాంగులు అంటారు; వారిని గౌరవించి సాయం చేయాలి. శరీరం శుభ్రంగా ఉంచి, మంచి ఆహారం తిని, భోజనానికి ముందు, తర్వాత సబ్బుతో చేతులు కడగాలి. ప్రేమ, భద్రత కలిగించేది మంచి స్పర్శ; భయం, ఇబ్బంది కలిగించేది చెడు స్పర్శ – అప్పుడు “వద్దు” అని గట్టిగా చెప్పి, అక్కడి నుంచి వెళ్లిపోయి, నమ్మకమైన పెద్దలకు చెప్పాలి.","pts": ["శరీరం 3 భాగాలు: తల (Head), మొండెం (Trunk), కాళ్లు-చేతులు (Limbs).","5 జ్ఞానేంద్రియాలు: కళ్లు – చూపు, చెవులు – వినికిడి, ముక్కు – వాసన, నాలుక – రుచి, చర్మం – స్పర్శ.","చేతులతో రాస్తాం, తింటాం, ఆడతాం; కాళ్లతో నడుస్తాం, పరుగెత్తుతాం. సైకిల్ తొక్కడానికి చాలా భాగాలు కలిసి పనిచేస్తాయి.","దివ్యాంగులు (Differently abled / CWSN) – వారిని గౌరవించి సాయం చేయాలి.","చేతులు కడిగే 8 దశలు: అరచేతులు, వేళ్ల మధ్య, చేతి వెనుక, బొటనవేలు, వేళ్ల వెనుక, గోళ్లు, మణికట్టు, కడిగి తుడవడం.","అక్టోబర్ 15 – ప్రపంచ చేతుల శుభ్రత దినం (Global Handwashing Day).","మంచి అలవాట్లు: రోజుకు రెండుసార్లు పళ్లు తోమడం, రోజూ స్నానం, చేతులు కడగడం, మూత పెట్టిన ఆహారం తినడం.","చెడు స్పర్శ అయితే: 1) “వద్దు! STOP” అని గట్టిగా చెప్పాలి 2) అక్కడి నుంచి వెళ్లిపోవాలి 3) అమ్మానాన్న / టీచర్‌కి చెప్పాలి. ఇది నీ తప్పు కాదు. CHILDLINE – 1098 (ఉచితం, 24 గంటలు)."],"w": [["Sense organs","జ్ఞానేంద్రియాలు"],["Head","తల"],["Trunk","మొండెం"],["Limbs","కాళ్లు, చేతులు"],["Breathe","శ్వాస తీసుకోవడం"],["Differently abled","దివ్యాంగులు"],["Hygiene","శుభ్రత"],["Good touch","మంచి స్పర్శ"],["Bad touch","చెడు స్పర్శ"],["Trusted adult","నమ్మకమైన పెద్దలు"]],"gr": {"t": "భాగం – దాని పని","p": ["కళ్లు → చూడటం","చెవులు → వినడం","ముక్కు → వాసన చూడటం, శ్వాస","నాలుక → రుచి చూడటం","చర్మం → స్పర్శ తెలుసుకోవడం"]},"qa": [["జ్ఞానేంద్రియాలు ఎన్ని? ఏవి?","ఐదు – కళ్లు, చెవులు, ముక్కు, నాలుక, చర్మం."],["భోజనానికి ముందు చేతులు ఎందుకు కడగాలి?","చేతులపై ఉన్న క్రిములు కడుపులోకి వెళ్లి జబ్బు చేయకుండా."],["మంచి స్పర్శ, చెడు స్పర్శ తేడా?","ప్రేమ, భద్రత కలిగించేది మంచి స్పర్శ; భయం, ఇబ్బంది, బాధ కలిగించేది చెడు స్పర్శ."],["ఎవరైనా ఇబ్బందిగా తాకితే ఏం చేయాలి?","“వద్దు” అని గట్టిగా చెప్పి, అక్కడి నుంచి వెళ్లిపోయి, అమ్మానాన్న లేదా టీచర్‌కి వెంటనే చెప్పాలి."]],"act": "కళ్లకు గంతలు కట్టి పువ్వు, గంట, తీపి, పుస్తకం, దూది లాంటి వస్తువులను వాసన, శబ్దం, స్పర్శతో గుర్తించే ఆట ఆడండి. 8 దశల్లో చేతులు కడగడం సాధన చేయండి.","kn": "చేతి ఐదు వేళ్ల పేర్లు: బొటనవేలు (Thumb), చూపుడు వేలు (Index), మధ్య వేలు (Middle), ఉంగరం వేలు (Ring), చిటికెన వేలు (Little).","qz": [["వాసన చూడటానికి సహాయపడే జ్ఞానేంద్రియం?","ముక్కు (Nose)","కళ్లు (Eyes)","చర్మం (Skin)","నాలుక (Tongue)"],["చూడటానికి సహాయపడేది?","కళ్లు","చెవులు","ముక్కు","చర్మం"],["రుచి తెలుసుకునేది?","నాలుక","చెవులు","కళ్లు","జుట్టు"],["జ్ఞానేంద్రియాలు ఎన్ని?","5","3","4","10"],["శరీరం మూడు భాగాలు?","తల, మొండెం, కాళ్లు-చేతులు","కళ్లు, ముక్కు, నోరు","చేతులు, వేళ్లు, గోళ్లు","తల, జుట్టు, మెడ"],["ఆడుకుని వచ్చాక తినే ముందు ఏం చేయాలి?","చేతులు కడగాలి","టీవీ చూడాలి","నిద్రపోవాలి","ఇంకా ఆడాలి"],["ప్రపంచ చేతుల శుభ్రత దినం ఎప్పుడు?","అక్టోబర్ 15","మార్చి 22","జూన్ 5","నవంబర్ 14"],["మంచి అలవాటు ఏది?","రోజుకు రెండుసార్లు పళ్లు తోమడం","మూత లేని ఆహారం తినడం","మురికి నీటిలో ఆడటం","స్నానం మానేయడం"],["ఎవరైనా ఇబ్బందిగా తాకితే ముందు ఏం చేయాలి?","“వద్దు” అని గట్టిగా చెప్పాలి","మౌనంగా ఉండాలి","వారితో వెళ్లాలి","ఎవరికీ చెప్పకూడదు"],["పిల్లల సహాయ ఫోన్ CHILDLINE నంబర్?","1098","100","108","1100"],["చూడలేని, వినలేని, నడవలేని వారిని ఏమంటారు?","దివ్యాంగులు","సోమరులు","అతిథులు","పండితులు"],["చర్మం ద్వారా తెలిసేది?","స్పర్శ","రుచి","వాసన","శబ్దం"]]},{"id": "ev5","no": 5,"t": "Food We Eat – మనం తినే ఆహారం","m": [9],"ty": "పాఠం","th": "ఆహారం, మంచి అలవాట్లు","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "అను కుటుంబం బాపట్ల బీచ్ ఫెస్టివల్‌కు వెళ్లాలనుకుంది – రొయ్యల వేపుడు, చేపల కూర, బాదం పాలు, కొబ్బరి నీళ్లు, బజ్జీలు, పునుగులు తినాలనుకున్నారు. “ఆహారం లేకుండా జీవితం సాగదు.” ఆహారం మనకు శక్తి, పెరుగుదల, ఆరోగ్యం ఇస్తుంది. మొక్కల నుంచి వేర్లు, కాండం, ఆకులు, పువ్వులు, పండ్లు, విత్తనాలు తింటాం. జంతువుల నుంచి పాలు, గుడ్లు, మాంసం, చేపలు వస్తాయి. కొన్ని పచ్చిగా, కొన్ని వండి తింటాం. ఆరోగ్యకరమైన ఆహారం తిని జంక్ ఫుడ్ మానేయాలి. పసిపిల్లలు, వృద్ధులకు మెత్తటి ఆహారం. బడిలో మధ్యాహ్న భోజనం పోషకాహారం ఇస్తుంది.","pts": ["ఆహారం: శక్తి, పెరుగుదల, ఆరోగ్యం, బలం ఇస్తుంది.","ధాన్యాలు: వరి (బియ్యం), గోధుమ; చిరుధాన్యాలు – సజ్జలు, సామలు, రాగులు, కొర్రలు.","వేర్లు: క్యారెట్, బీట్‌రూట్, ముల్లంగి • ఆకులు: తోటకూర, మునగాకు, పాలకూర, కరివేపాకు • పువ్వులు: అరటి పువ్వు, కాలీఫ్లవర్, లవంగాలు • విత్తనాలు: బఠాణీ, బొబ్బర్లు, వేరుశనగ, జీడిపప్పు, పప్పులు.","చెరకు నుంచి బెల్లం, చక్కెర; వేరుశనగ, నువ్వులు, ఆవాలు, పొద్దుతిరుగుడు గింజల నుంచి నూనె.","జంతువుల నుంచి: పాలు (పెరుగు, నెయ్యి, వెన్న, పన్నీర్), గుడ్లు, మాంసం, చేపలు, రొయ్యలు, పీతలు.","పచ్చిగా తినేవి: క్యారెట్, ఉల్లి, కీర • వండి తినేవి: బియ్యం, మాంసం, వంకాయ.","మంచి అలవాట్లు: చేతులు కడగడం, నెమ్మదిగా నమిలి తినడం, ఆహారం వృథా చేయకపోవడం, నీళ్లు ఎక్కువగా తాగడం, చిప్స్ – కూల్‌డ్రింక్స్ మానేయడం.","ఆంధ్ర రుచులు: పులిహోర, పప్పు, సాంబారు, రసం, గోంగూర పచ్చడి; పండుగ తీపి – పూతరేకులు, బొబ్బట్లు."],"w": [["Food","ఆహారం"],["Energy","శక్తి"],["Millets","చిరుధాన్యాలు"],["Raw food","పచ్చి ఆహారం"],["Cooked food","వండిన ఆహారం"],["Junk food","జంక్ ఫుడ్ (హానికరమైన తిండి)"],["Nutritious","పోషకమైన"],["Poultry farm","కోళ్ల ఫారం"],["Dairy farm","పాడి కేంద్రం"],["Mid-day meal","మధ్యాహ్న భోజనం"]],"gr": {"t": "చేద్దాం: నిమ్మరసం తయారీ","p": ["నిమ్మకాయను శుభ్రంగా కడగాలి.","పెద్దల సహాయంతో రెండు ముక్కలుగా కోయాలి.","గ్లాసులో రసం పిండి, గింజలు తీసేయాలి.","నీళ్లు, కొంచెం చక్కెర, చిటికెడు ఉప్పు వేసి కలపాలి – కూల్‌డ్రింక్ కంటే ఆరోగ్యం!"]},"qa": [["అన్ని జీవులకు ఆహారం ఎందుకు కావాలి?","శక్తి, పెరుగుదల, ఆరోగ్యం కోసం. ఆహారం లేకుండా జీవించలేం."],["మొక్కల నుంచి, జంతువుల నుంచి వచ్చే ఆహారానికి రెండేసి ఉదాహరణలు?","మొక్కల నుంచి: బియ్యం, మామిడి. జంతువుల నుంచి: పాలు, గుడ్లు."],["కొన్ని ఆహారాలు ఎందుకు వండి తినాలి?","బియ్యం, మాంసం లాంటివి పచ్చిగా తినలేం; వండితే మెత్తగా, సురక్షితంగా, తేలికగా అరుగుతాయి."],["పసిపిల్లలు, వృద్ధులు మెత్తటి ఆహారం ఎందుకు తింటారు?","వారికి పళ్లు లేక నమలలేరు."],["శుభ దిన భోజనం (తిథి భోజనం) అంటే?","పండుగలు, పుట్టినరోజుల్లో గ్రామస్తులు బడి పిల్లలకు పోషకాహారం అందించే కార్యక్రమం."]],"act": "ఇంట్లో పాలతో చేసే 4 పదార్థాలు రాయండి. ఆరోగ్యకరమైన ఆహారానికి ఆకుపచ్చ, జంక్ ఫుడ్‌కి ఎరుపు గడి గీయండి. పెద్దల సహాయంతో నిమ్మరసం తయారు చేయండి.","kn": "మన ఆహారం నేరుగా ప్లేట్‌కి రాదు – పొలాల్లో పంటలు, కోళ్ల ఫారాల్లో గుడ్లు, పాడి కేంద్రాల్లో పాలు ఉత్పత్తి అయి దుకాణాలకు వస్తాయి. పుట్టగొడుగు (Mushroom) లో పోషకాలు ఎక్కువ.","qz": [["ఆహారం మనకు ఇచ్చేది?","శక్తి, పెరుగుదల, ఆరోగ్యం","నిద్ర మాత్రమే","జబ్బులు","అలసట"],["వేరును ఆహారంగా తినేది?","క్యారెట్","కాలీఫ్లవర్","తోటకూర","బఠాణీ"],["పువ్వును ఆహారంగా తినేది?","కాలీఫ్లవర్","క్యారెట్","బంగాళాదుంప","వేరుశనగ"],["చెరకు నుంచి వచ్చేది?","బెల్లం, చక్కెర","నూనె","పాలు","ఉప్పు"],["గుడ్లు ఎక్కడ ఉత్పత్తి అవుతాయి?","కోళ్ల ఫారం (Poultry farm)","పాడి కేంద్రం (Dairy farm)","పొలం","దుకాణం"],["పాలతో చేసేది?","పెరుగు","బెల్లం","నూనె","పప్పు"],["పచ్చిగా తినగలిగేది?","క్యారెట్","బియ్యం","మాంసం","గోధుమ"],["జంక్ ఫుడ్ ఏది?","పొటాటో చిప్స్","పండ్లు","చిలగడదుంప","పాలు"],["వేసవిలో కూల్‌డ్రింక్ బదులు మంచిది?","నిమ్మరసం","సోడా","చాక్లెట్","చిప్స్"],["పసిపిల్లలకు మెత్తటి ఆహారం ఎందుకు?","పళ్లు ఉండవు, నమలలేరు","ఇష్టం లేక","రుచి కోసం","డబ్బు ఆదా"],["గోంగూర పచ్చడి దేనితో చేస్తారు?","పుల్లని ఆకులతో","పండ్లతో","పాలతో","గుడ్లతో"],["మంచి ఆహారపు అలవాటు?","నెమ్మదిగా నమిలి తినడం","ఆహారం వృథా చేయడం","కడగని పండ్లు తినడం","చేతులు కడగకపోవడం"],["సజ్జలు, రాగులు, కొర్రలు ఏవి?","చిరుధాన్యాలు (Millets)","పండ్లు","కూరగాయలు","పప్పులు"]]},{"id": "ev6","no": 6,"t": "Water – A Precious Gift – నీరు విలువైన బహుమతి","m": [10],"ty": "పాఠం","th": "నీరు, నీటి సంరక్షణ","by": "Our Wonderful World – 3 (సెమిస్టర్-1)","sum": "ఈ పాఠంలో ఒక వర్షపు చుక్క తన కథ చెబుతుంది: “నేను మేఘాల నుంచి పడతాను. నేను లేకుండా మీరు, మొక్కలు, జంతువులు బతకలేరు.” తాగడానికి, స్నానానికి, బట్టలు ఉతకడానికి, మొక్కలకు, వ్యవసాయానికి, నిర్మాణాలకు, మంటలు ఆర్పడానికి, చేపలు – రొయ్యల పెంపకానికి నీరు కావాలి. వర్షమే ముఖ్యమైన నీటి వనరు. వేసవిలో బావులు, చెరువులు ఎండిపోయి నీటి కొరత వస్తుంది. నీరు కలుషితం అవుతుంది కాబట్టి కాచి చల్లార్చి లేదా ఫిల్టర్ చేసిన సురక్షితమైన నీరే తాగాలి. నీటిని వృథా చేయకూడదు.","pts": ["వర్షం – ముఖ్యమైన నీటి వనరు.","సహజ వనరులు: సముద్రాలు, నదులు, సరస్సులు, వాగులు, చెరువులు, ఊటలు.","మానవ నిర్మిత వనరులు: ఆనకట్టలు, బావులు, గొట్టపు బావులు, చేతి పంపులు, కాలువలు, బోరుబావులు.","నీటి శుద్ధి: కాచి చల్లార్చడం, ఫిల్టర్ / ప్యూరిఫైయర్. మూత పెట్టిన శుభ్రమైన పాత్రల్లో నిల్వ చేయాలి.","వాటర్ బాటిల్‌ను ఉప్పు, గోరువెచ్చని నీళ్లు, బ్రష్‌తో తరచూ కడగాలి.","వాటర్ బెల్ – బడిలో రోజుకు మూడుసార్లు నీళ్లు తాగమని గుర్తు చేసే గంట.","నీరు ఆదా: చిన్న గ్లాసు వాడటం, గిన్నెలో కూరగాయలు కడగడం, బకెట్ పొంగకుండా చూడటం, పని కాగానే ట్యాప్ కట్టేయడం, లీకులు సరిచేయడం, ట్యాంక్ నిండగానే మోటార్ ఆపడం.","మార్చి 22 – ప్రపంచ నీటి దినోత్సవం (World Water Day)."],"w": [["Precious","విలువైన"],["Source","వనరు"],["Scarcity","కొరత"],["Polluted","కలుషితమైన"],["Safe water","సురక్షితమైన నీరు"],["Purify","శుద్ధి చేయడం"],["Dam","ఆనకట్ట"],["Canal","కాలువ"],["Agriculture","వ్యవసాయం"],["Aquaculture","చేపలు, రొయ్యల పెంపకం"],["Wastage","వృథా"]],"gr": {"t": "ఆలోచించండి","p": ["భూమిపై మూడు వంతులు నీరే అయినా తాగే మంచి నీరు చాలా తక్కువ – అందుకే ఆదా చేయాలి.","బడిలో ట్యాప్ నుంచి నీరు పొంగిపోతుంటే రమ వెంటనే ట్యాప్ కట్టేసి టీచర్‌కు చెప్పాలి.","అన్ని వనరుల నీళ్లూ నేరుగా తాగకూడదు – కలుషితమై ఉండవచ్చు."]},"qa": [["మనకు నీరు ఎందుకు కావాలి?","తాగడానికి, వంటకు, స్నానానికి, మొక్కలకు, వ్యవసాయానికి – నీరు లేకుండా ఎవరూ బతకలేరు."],["రెండు నీటి వనరుల పేర్లు?","నది, బావి (చెరువు, బోరుబావి కూడా)."],["నీటిని ఎలా శుద్ధి చేయాలి?","కాచి చల్లార్చి లేదా ఫిల్టర్‌తో."],["నీరు తక్కువైతే ఏమవుతుంది?","తాగడానికి, పంటలకు నీళ్లు ఉండవు; దూరం నడవాల్సి లేదా ట్యాంకర్ కోసం ఎదురుచూడాల్సి వస్తుంది."],["చేతులు కడిగిన వెంటనే ఏం చేయాలి?","ట్యాప్ కట్టేయాలి."]],"act": "మీ ఇంట్లో నీళ్లు నిల్వ చేసే పాత్రల బొమ్మ గీయండి. మీ ఊరిలో ఉన్న నీటి వనరులకు ✓ పెట్టండి. “నీరు ఆదా చేద్దాం” నినాదం రాసి తరగతిలో అతికించండి. ఉప్పు, గోరువెచ్చని నీళ్లతో వాటర్ బాటిల్ కడగండి.","kn": "సీల్ లేని, ఎక్కువ కాలం నిల్వ ఉన్న బాటిళ్లు, ప్యాకెట్ల నీళ్లు వాడకూడదు. ప్రభుత్వం సురక్షిత తాగునీటి పథకం ద్వారా శుద్ధ జలం అందిస్తోంది.","qz": [["ముఖ్యమైన నీటి వనరు?","వర్షం","ట్యాంకర్","బాటిల్","బకెట్"],["సహజ నీటి వనరు ఏది?","నది","ఆనకట్ట","బోరుబావి","చేతి పంపు"],["మానవ నిర్మిత నీటి వనరు?","ఆనకట్ట (Dam)","సముద్రం","ఊట","సరస్సు"],["నీటిని శుద్ధి చేసే సులభ పద్ధతి?","కాచి చల్లార్చడం","ఉప్పు వేయడం","రంగు కలపడం","మట్టి కలపడం"],["ప్రపంచ నీటి దినోత్సవం?","మార్చి 22","అక్టోబర్ 15","జూన్ 5","ఆగస్టు 15"],["చేతులు కడిగాక వెంటనే?","ట్యాప్ కట్టేయాలి","ట్యాప్ వదిలేయాలి","స్నేహితుడిని పిలవాలి","వెళ్లిపోవాలి"],["నీరు ఆదా చేసే అలవాటు?","గిన్నెలో కూరగాయలు కడగడం","ట్యాప్ కింద వదిలి కడగడం","బకెట్ పొంగనివ్వడం","లీకులు వదిలేయడం"],["వాటర్ బెల్ ఎందుకు?","నీళ్లు తాగమని గుర్తు చేయడానికి","భోజనానికి","ఆటకు","ఇంటికి వెళ్లడానికి"],["వాటర్ బాటిల్ ఎలా కడగాలి?","ఉప్పు, గోరువెచ్చని నీళ్లు, బ్రష్‌తో","నూనెతో","కడగనవసరం లేదు","మట్టితో"],["చేపలు, రొయ్యల పెంపకాన్ని ఏమంటారు?","Aquaculture","Agriculture","Construction","Furniture"],["“Scarcity” అంటే?","కొరత","వరద","వర్షం","శుభ్రత"],["నీరు ఎక్కువగా దేని వల్ల కలుషితం అవుతుంది?","మనుషుల పనుల వల్ల","చంద్రుని వల్ల","మేఘాల వల్ల","చెట్ల వల్ల"]]}]};
